# --- Private: endpoint detection ---

def _walk_endpoints(self, node: Node, file_path: str, endpoints: list[EndpointInfo]):
    """Walk decorated function definitions to find route decorators."""
    if node.type == "decorated_definition":
        self._check_decorated_endpoint(node, file_path, endpoints)

    for child in node.children:
        self._walk_endpoints(child, file_path, endpoints)

def _check_decorated_endpoint(self, node: Node, file_path: str, endpoints: list[EndpointInfo]):
    """Check if a decorated definition has a route decorator."""
    frameworks = get_endpoint_frameworks("python")
    decorators = []
    func_node = None

    for child in node.children:
        if child.type == "decorator":
            decorators.append(child)
        elif child.type == "function_definition":
            func_node = child

    if not func_node:
        return

    func_name = ""
    name_node = func_node.child_by_field_name("name")
    if name_node:
        func_name = name_node.text.decode("utf-8")

    # Find enclosing class
    class_name = ""
    current = node.parent
    while current:
        if current.type == "class_definition":
            cn = current.child_by_field_name("name")
            if cn:
                class_name = cn.text.decode("utf-8")
            break
        current = current.parent

    line = func_node.start_point[0] + 1

    for dec in decorators:
        dec_text = dec.text.decode("utf-8").lstrip("@")
        # Match against framework patterns
        for fw_name, fw_config in frameworks.items():
            for pattern in fw_config.get("decorators", []):
                pat = pattern["pattern"]
                if dec_text.startswith(pat + "(") or dec_text == pat:
                    path = self._extract_decorator_arg(dec)
                    op = pattern.get("operation", "DYNAMIC")
                    if op == "DYNAMIC":
                        op = self._infer_operation_from_decorator(dec_text)
                    endpoints.append(EndpointInfo(
                        type=pattern.get("type", "REST"),
                        path=path,
                        operation=op,
                        handler_class=class_name,
                        handler_method=func_name,
                        file=file_path,
                        line=line,
                        direction="INBOUND",
                        protocol=pattern.get("protocol", "HTTP"),
                        framework=fw_name,
                        confidence=0.90,
                    ))

def _extract_decorator_arg(self, decorator_node: Node) -> str:
    """Extract the first string argument from a decorator like @app.get('/path')."""
    for child in decorator_node.children:
        if child.type == "call":
            args = child.child_by_field_name("arguments")
            if args:
                for arg in args.children:
                    if arg.type == "string":
                        return arg.text.decode("utf-8").strip("\"'")
    return ""

def _infer_operation_from_decorator(self, dec_text: str) -> str:
    """Infer HTTP method from decorator text like 'app.route' with methods=['POST']."""
    lower = dec_text.lower()
    for method in ["get", "post", "put", "delete", "patch"]:
        if f".{method}" in lower or f"'{method}'" in lower:
            return method.upper()
    return "DYNAMIC"

# --- Private: data movement detection ---

def _walk_data_movements(self, node: Node, file_path: str,
                          movements: list[DataMovementInfo], patterns: list[dict]):
    """Walk call expressions to find data movement patterns."""
    if node.type == "call":
        self._check_data_movement(node, file_path, movements, patterns)

    for child in node.children:
        self._walk_data_movements(child, file_path, movements, patterns)

def _check_data_movement(self, node: Node, file_path: str,
                          movements: list[DataMovementInfo], patterns: list[dict]):
    """Check if a call matches a data movement pattern."""
    func = node.child_by_field_name("function")
    if not func:
