        elif pat_prefix and receiver and receiver.startswith(pat_prefix):
            matched = True

        if matched:
            target = self._extract_first_string_arg(node) or f"{receiver or ''}.{method}"
            movements.append(DataMovementInfo(
                source_class=source_class,
                source_method=source_method,
                target=target,
                target_type=pat.get("target_type", "UNKNOWN"),
                direction=pat.get("direction", "REQUEST_RESPONSE"),
                mechanism=pat.get("mechanism", ""),
                file=file_path,
                line=line,
                confidence=0.80,
            ))
            break

def _extract_first_string_arg(self, call_node: Node) -> str:
    """Extract the first string argument from a call."""
    args = call_node.child_by_field_name("arguments")
    if args:
        for arg in args.children:
