# --- Private: endpoint detection ---

def _walk_go_endpoints(self, node: Node, file_path: str,
                       endpoints: list[EndpointInfo], frameworks: dict):
    if node.type == "call_expression":
        self._check_go_endpoint(node, file_path, endpoints, frameworks)

    for child in node.children:
        self._walk_go_endpoints(child, file_path, endpoints, frameworks)

def _check_go_endpoint(self, node: Node, file_path: str,
                        endpoints: list[EndpointInfo], frameworks: dict):
    func = node.child_by_field_name("function")
    if not func:
        return

    receiver = None
    method = None

    if func.type == "selector_expression":
        operand = func.child_by_field_name("operand")
        field_node = func.child_by_field_name("field")
        if operand and field_node:
            receiver = operand.text.decode("utf-8")
            method = field_node.text.decode("utf-8")
    elif func.type == "identifier":
        method = func.text.decode("utf-8")

    if not method:
        return

    caller = self._find_enclosing_scope(node)
    line = node.start_point[0] + 1

    for fw_name, fw_config in frameworks.items():
        for pattern in fw_config.get("call_patterns", []):
            suffix = pattern.get("receiver_suffix", "")
            methods = pattern.get("methods", [])

            if method in methods and (not suffix or (receiver and receiver.endswith(suffix))):
                path = self._extract_go_first_string_arg(node)
                op = pattern.get("operation", method.upper())
                if op == "DYNAMIC":
                    op = method.upper()
                endpoints.append(EndpointInfo(
                    type=pattern.get("type", "REST"),
                    path=path,
                    operation=op,
                    handler_class="",
                    handler_method=caller,
                    file=file_path,
                    line=line,
                    direction="INBOUND",
                    protocol=pattern.get("protocol", "HTTP"),
                    framework=fw_name,
                    confidence=0.85,
                ))
                return

def _extract_go_first_string_arg(self, call_node: Node) -> str:
    args = call_node.child_by_field_name("arguments")
    if args:
        for arg in args.children:
            if arg.type == "interpreted_string_literal":
                return arg.text.decode("utf-8").strip('"')
            if arg.type == "raw_string_literal":
                return arg.text.decode("utf-8").strip('`')
    return ""

# --- Private: data movement detection ---

def _walk_go_data_movements(self, node: Node, file_path: str,
                             movements: list[DataMovementInfo], patterns: list[dict]):
    if node.type == "call_expression":
        self._check_go_data_movement(node, file_path, movements, patterns)

    for child in node.children:
        self._walk_go_data_movements(child, file_path, movements, patterns)

def _check_go_data_movement(self, node: Node, file_path: str,
                             movements: list[DataMovementInfo], patterns: list[dict]):
    func = node.child_by_field_name("function")
    if not func:
        return

    receiver = None
    method = None

    if func.type == "selector_expression":
        operand = func.child_by_field_name("operand")
        field_node = func.child_by_field_name("field")
        if operand and field_node:
            receiver = operand.text.decode("utf-8")
            method = field_node.text.decode("utf-8")
    elif func.type == "identifier":
        method = func.text.decode("utf-8")

    if not method:
        return

    caller = self._find_enclosing_scope(node)
    caller_parts = caller.rsplit(".", 1)
    source_class = caller_parts[0] if len(caller_parts) > 1 else ""
    source_method = caller_parts[-1]
    line = node.start_point[0] + 1

    for pat in patterns:
        if method not in pat.get("methods", []):
            continue

        pat_receiver = pat.get("receiver")
        matched = False
        if pat_receiver and receiver and pat_receiver in receiver.lower():
            matched = True

        if matched:
            target = self._extract_go_first_string_arg(node) or f"{receiver}.{method}"
            movements.append(DataMovementInfo(
                source_class=source_class,
                source_method=source_method,
                target=target,
                target_type=pat.get("target_type", "UNKNOWN"),
                direction=pat.get("direction", "REQUEST_RESPONSE"),
                mechanism=pat.get("mechanism", ""),
                file=file_path,
                line=line,
                confidence=0.80,
            ))
            break

