"""Java tree-sitter extractor.

Extracts calls, imports, assignments, and type annotations from Java ASTs.
Handles: method_invocation, object_creation_expression, import_declaration,
local_variable_declaration, field_declaration, class_declaration.
"""
from typing import Optional, Any

import tree_sitter_java as ts_java
from tree_sitter import Language, Parser, Node

from src.ast.treesitter_models import RawCallSite
from src.ast.extractors.base import LanguageExtractor
from src.ast.models import EndpointInfo, DataMovementInfo
from src.ast.extractors.endpoint_config import get_endpoint_frameworks, get_data_movement_patterns

JAVA_LANGUAGE = Language(ts_java.language())


class JavaExtractor(LanguageExtractor):
    """Extract call sites, imports, assignments, and annotations from Java source."""

    def __init__(self):
        self._parser = Parser(JAVA_LANGUAGE)

    @property
    def file_extensions(self) -> list[str]:
        return [".java"]

    @property
    def grammar(self) -> Any:
        return JAVA_LANGUAGE

    def extract_calls(self, source: bytes, file_path: str) -> list[RawCallSite]:
        tree = self._parser.parse(source)
        calls: list[RawCallSite] = []
        self._walk_calls(tree.root_node, file_path, calls)
        return calls

    def extract_imports(self, source: bytes) -> list[tuple[str, list[str], bool]]:
        tree = self._parser.parse(source)
        imports: list[tuple[str, list[str], bool]] = []

        for node in tree.root_node.children:
            if node.type != "import_declaration":
                continue
            # import java.util.List; or import java.util.*;
            text = node.text.decode("utf-8").strip().rstrip(";")
            # Remove "import " and optional "static "
            path = text.replace("import ", "").replace("static ", "").strip()
            if path.endswith(".*"):
                module = path[:-2]
                imports.append((module, ["*"], False))
            else:
                parts = path.rsplit(".", 1)
                module = parts[0] if len(parts) > 1 else path
                name = parts[1] if len(parts) > 1 else path
                imports.append((module, [name], False))

        return imports

    def extract_assignments(self, source: bytes) -> dict[str, str]:
        tree = self._parser.parse(source)
        assignments: dict[str, str] = {}
        self._walk_assignments(tree.root_node, None, assignments)
        return assignments

    def extract_annotations(self, source: bytes) -> dict[str, str]:
        tree = self._parser.parse(source)
        annotations: dict[str, str] = {}
        self._walk_annotations(tree.root_node, None, annotations)
        return annotations

    def extract_endpoints(self, source: bytes, file_path: str) -> list[EndpointInfo]:
        """Detect Spring annotations (@GetMapping, @PostMapping, etc.) on methods."""
        tree = self._parser.parse(source)
        endpoints: list[EndpointInfo] = []
        frameworks = get_endpoint_frameworks("java")
        self._walk_endpoint_annotations(tree.root_node, file_path, endpoints, frameworks, None)
        return endpoints

    def extract_data_movements(self, source: bytes, file_path: str) -> list[DataMovementInfo]:
        """Detect RestTemplate, JPA Repository, KafkaTemplate, etc."""
        tree = self._parser.parse(source)
        movements: list[DataMovementInfo] = []
        patterns = get_data_movement_patterns("java")
        self._walk_java_data_movements(tree.root_node, file_path, movements, patterns)
        return movements

    # --- Endpoint detection ---

    def _walk_endpoint_annotations(self, node: Node, file_path: str,
                                    endpoints: list[EndpointInfo],
                                    frameworks: dict, class_name: Optional[str]):
        """Walk class/method declarations looking for endpoint annotations."""
        if node.type in ("class_declaration", "interface_declaration"):
            name = node.child_by_field_name("name")
            cls = name.text.decode("utf-8") if name else class_name
            for child in node.children:
                self._walk_endpoint_annotations(child, file_path, endpoints, frameworks, cls)
            return

        if node.type == "method_declaration":
            self._check_java_method_endpoint(node, file_path, endpoints, frameworks, class_name)

        for child in node.children:
            self._walk_endpoint_annotations(child, file_path, endpoints, frameworks, class_name)

    def _check_java_method_endpoint(self, node: Node, file_path: str,
                                     endpoints: list[EndpointInfo],
                                     frameworks: dict, class_name: Optional[str]):
        """Check if a method has endpoint annotations."""
        method_name = ""
        name_node = node.child_by_field_name("name")
        if name_node:
            method_name = name_node.text.decode("utf-8")

        line = node.start_point[0] + 1

        # Collect annotations (modifiers contain annotations in Java grammar)
        for child in node.children:
            if child.type == "modifiers":
                for mod in child.children:
                    if mod.type in ("annotation", "marker_annotation"):
                        ann_name = self._get_annotation_name(mod)
                        self._match_java_annotation(
                            ann_name, mod, file_path, class_name or "",
                            method_name, line, endpoints, frameworks
                        )

    def _get_annotation_name(self, annotation_node: Node) -> str:
        """Extract annotation name from @GetMapping or @GetMapping(...)."""
        for child in annotation_node.children:
            if child.type == "identifier":
                return child.text.decode("utf-8")
            if child.type == "scoped_identifier":
                return child.text.decode("utf-8").split(".")[-1]
        return ""

    def _match_java_annotation(self, ann_name: str, ann_node: Node,
                                file_path: str, class_name: str,
                                method_name: str, line: int,
                                endpoints: list[EndpointInfo], frameworks: dict):
        """Match an annotation name against configured framework patterns."""
        for fw_name, fw_config in frameworks.items():
            for pattern in fw_config.get("annotations", []):
                if ann_name == pattern["pattern"]:
                    path = self._extract_annotation_string_arg(ann_node)
                    op = pattern.get("operation", "DYNAMIC")
                    endpoints.append(EndpointInfo(
                        type=pattern.get("type", "REST"),
                        path=path,
                        operation=op,
                        handler_class=class_name,
                        handler_method=method_name,
                        file=file_path,
                        line=line,
                        direction="INBOUND",
                        protocol=pattern.get("protocol", "HTTP"),
                        framework=fw_name,
                        confidence=0.90,
                    ))
                    return

    def _extract_annotation_string_arg(self, annotation_node: Node) -> str:
        """Extract string value from annotation like @GetMapping('/path') or @GetMapping(value='/path')."""
        for child in annotation_node.children:
            if child.type == "annotation_argument_list":
                for arg in child.children:
                    if arg.type == "string_literal":
                        return arg.text.decode("utf-8").strip('"')
                    if arg.type == "element_value_pair":
                        for ev in arg.children:
                            if ev.type == "string_literal":
                                return ev.text.decode("utf-8").strip('"')
        return ""

    # --- Data movement detection ---

    def _walk_java_data_movements(self, node: Node, file_path: str,
                                   movements: list[DataMovementInfo], patterns: list[dict]):
        """Walk method invocations to find data movement patterns."""
        if node.type == "method_invocation":
            self._check_java_data_movement(node, file_path, movements, patterns)

        for child in node.children:
            self._walk_java_data_movements(child, file_path, movements, patterns)

    def _check_java_data_movement(self, node: Node, file_path: str,
                                   movements: list[DataMovementInfo], patterns: list[dict]):
        """Check if a method invocation matches a data movement pattern."""
        name_node = node.child_by_field_name("name")
        obj_node = node.child_by_field_name("object")
        if not name_node:
            return

        method = name_node.text.decode("utf-8")
        receiver = obj_node.text.decode("utf-8") if obj_node else None

        caller = self._find_enclosing_scope(node)
        caller_parts = caller.rsplit(".", 1)
        source_class = caller_parts[0] if len(caller_parts) > 1 else ""
        source_method = caller_parts[-1]
        line = node.start_point[0] + 1

        for pat in patterns:
            if method not in pat.get("methods", []):
                continue

            pat_receiver = pat.get("receiver")
            pat_suffix = pat.get("receiver_suffix")

            matched = False
            if pat_receiver and receiver and pat_receiver.lower() in receiver.lower():
                matched = True
            elif pat_suffix and receiver and receiver.endswith(pat_suffix):
                matched = True

            if matched:
                target = self._extract_java_first_string_arg(node) or f"{receiver}.{method}"
                movements.append(DataMovementInfo(
                    source_class=source_class,
                    source_method=source_method,
                    target=target,
                    target_type=pat.get("target_type", "UNKNOWN"),
                    direction=pat.get("direction", "REQUEST_RESPONSE"),
                    mechanism=pat.get("mechanism", ""),
                    file=file_path,
                    line=line,
                    confidence=0.80,
                ))
                break

    def _extract_java_first_string_arg(self, node: Node) -> str:
        """Extract the first string argument from a method invocation."""
        args = node.child_by_field_name("arguments")
        if args:
            for arg in args.children:
                if arg.type == "string_literal":
                    return arg.text.decode("utf-8").strip('"')
        return ""

    # --- Call extraction ---

    def _walk_calls(self, node: Node, file_path: str, calls: list[RawCallSite]):
        if node.type == "method_invocation":
            call = self._extract_method_invocation(node, file_path)
            if call:
                calls.append(call)

        elif node.type == "object_creation_expression":
            call = self._extract_object_creation(node, file_path)
            if call:
                calls.append(call)

        for child in node.children:
            self._walk_calls(child, file_path, calls)

    def _extract_method_invocation(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        name_node = node.child_by_field_name("name")
        obj_node = node.child_by_field_name("object")
        if not name_node:
            return None

        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1
        method = name_node.text.decode("utf-8")
        receiver = obj_node.text.decode("utf-8") if obj_node else None

        return RawCallSite(
            file_path=file_path,
            caller_name=caller,
            receiver=receiver,
            method=method,
            line=line,
        )

    def _extract_object_creation(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        type_node = node.child_by_field_name("type")
        if not type_node:
            return None

        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1
        # Extract base type (strip generics)
        type_name = self._extract_base_type(type_node)

        return RawCallSite(
            file_path=file_path,
            caller_name=caller,
            receiver=None,
            method=f"new {type_name}",
            line=line,
        )

    def _find_enclosing_scope(self, node: Node) -> str:
        current = node.parent
        method_name = None
        class_name = None

        while current:
            if current.type == "method_declaration" and method_name is None:
                name = current.child_by_field_name("name")
                if name:
                    method_name = name.text.decode("utf-8")

            elif current.type == "constructor_declaration" and method_name is None:
                name = current.child_by_field_name("name")
                if name:
                    method_name = f"<init:{name.text.decode('utf-8')}>"

            elif current.type in ("class_declaration", "interface_declaration",
                                   "enum_declaration") and class_name is None:
                name = current.child_by_field_name("name")
                if name:
                    class_name = name.text.decode("utf-8")

            current = current.parent

        if class_name and method_name:
            return f"{class_name}.{method_name}"
        elif class_name:
            return class_name
        elif method_name:
            return method_name
        return "<module>"

    # --- Assignments ---

    def _walk_assignments(self, node: Node, scope: Optional[str], result: dict):
        if node.type in ("class_declaration", "interface_declaration", "enum_declaration"):
            name = node.child_by_field_name("name")
            cls = name.text.decode("utf-8") if name else scope
            for child in node.children:
                self._walk_assignments(child, cls, result)
            return

        if node.type == "method_declaration":
            name = node.child_by_field_name("name")
            fn = name.text.decode("utf-8") if name else None
            method_scope = f"{scope}.{fn}" if scope and fn else fn
            for child in node.children:
                self._walk_assignments(child, method_scope, result)
            return

        # List<String> items = new ArrayList<>(); or Database db = new Database();
        if node.type == "local_variable_declaration":
            type_name = self._extract_decl_type(node)
            declarator = node.child_by_field_name("declarator")
            if declarator and type_name:
                var_name = declarator.child_by_field_name("name")
                value = declarator.child_by_field_name("value")
                if var_name:
                    prefix = f"{scope}." if scope else ""
                    # Prefer RHS type for new expressions
                    rhs_type = self._resolve_rhs(value) if value else None
                    result[f"{prefix}{var_name.text.decode('utf-8')}"] = rhs_type or type_name

        if node.type == "field_declaration":
            type_name = self._extract_decl_type(node)
            declarator = node.child_by_field_name("declarator")
            if declarator and type_name:
                var_name = declarator.child_by_field_name("name")
                if var_name:
                    prefix = f"{scope}." if scope else ""
                    result[f"{prefix}{var_name.text.decode('utf-8')}"] = type_name

        for child in node.children:
            self._walk_assignments(child, scope, result)

    def _extract_decl_type(self, node: Node) -> Optional[str]:
        type_node = node.child_by_field_name("type")
        if type_node:
            return self._extract_base_type(type_node)
        return None

    def _resolve_rhs(self, node: Node) -> Optional[str]:
        if not node:
            return None
        if node.type == "object_creation_expression":
            type_node = node.child_by_field_name("type")
            if type_node:
                return self._extract_base_type(type_node)
        return None

    # --- Annotations (type info) ---

    def _walk_annotations(self, node: Node, scope: Optional[str], result: dict):
        if node.type in ("class_declaration", "interface_declaration", "enum_declaration"):
            name = node.child_by_field_name("name")
            cls = name.text.decode("utf-8") if name else scope
            for child in node.children:
                self._walk_annotations(child, cls, result)
            return

        if node.type == "method_declaration":
            name = node.child_by_field_name("name")
            fn = name.text.decode("utf-8") if name else None
            method_scope = f"{scope}.{fn}" if scope and fn else fn
            # Extract parameter types
            params = node.child_by_field_name("parameters")
            if params:
                for param in params.named_children:
                    if param.type == "formal_parameter":
                        ptype = param.child_by_field_name("type")
                        pname = param.child_by_field_name("name")
                        if ptype and pname:
                            prefix = f"{method_scope}." if method_scope else ""
                            result[f"{prefix}{pname.text.decode('utf-8')}"] = \
                                self._extract_base_type(ptype)
            for child in node.children:
                self._walk_annotations(child, method_scope, result)
            return

        for child in node.children:
            self._walk_annotations(child, scope, result)

    # --- Helpers ---

    def _extract_base_type(self, type_node: Node) -> str:
        """Extract base type name, stripping generics. List<String> → List."""
        if type_node.type == "generic_type":
            for child in type_node.children:
                if child.type == "type_identifier":
                    return child.text.decode("utf-8")
        if type_node.type == "type_identifier":
            return type_node.text.decode("utf-8")
        if type_node.type == "scoped_type_identifier":
            return type_node.text.decode("utf-8").replace(".", "_")
        return type_node.text.decode("utf-8").split("<")[0].split("[")[0]

