def _run_extraction(repo_path: Path, extensions: list[str]):
    """Run tree-sitter extraction on a repo, return merged results."""
    reset_caches()
    files = []
    for ext in extensions:
        files.extend(str(f) for f in repo_path.rglob(f"*{ext}")
                     if ".git" not in str(f) and "node_modules" not in str(f)
                     and "vendor" not in str(f)
                     and not any(p in f.name.lower() for p in ["test", "spec", "mock"]))
    if not files:
        pytest.skip(f"No source files found in {repo_path}")

    provider = TreeSitterProvider()
