    def extract_endpoints(self, source: bytes, file_path: str) -> list[EndpointInfo]:
        """Detect FastAPI/Flask route decorators and Celery tasks."""
        tree = self._parser.parse(source)
        endpoints: list[EndpointInfo] = []
        self._walk_endpoints(tree.root_node, file_path, endpoints)
        return endpoints

    def extract_data_movements(self, source: bytes, file_path: str) -> list[InteractionInfo]:
        """Detect outbound HTTP, DB, MQ, cache, file I/O, gRPC calls."""
        tree = self._parser.parse(source)
        movements: list[InteractionInfo] = []
        patterns = get_interaction_patterns("python")
        self._walk_data_movements(tree.root_node, file_path, movements, patterns)

        # gRPC: if file imports grpc, match calls on *_stub receivers
        imports = self.extract_imports(source)
        has_grpc = any("grpc" in mod for mod, _, _ in imports)
        if has_grpc:
            self._walk_python_grpc(tree.root_node, file_path, movements)

        return movements

    def _walk_python_grpc(self, node: Node, file_path: str, movements: list[InteractionInfo]):
        """Detect Python gRPC stub calls: stub.SayHello(), stub.GetFeature()."""
        if node.type == "call":
            func = node.child_by_field_name("function")
            if func and func.type == "attribute":
                obj = func.child_by_field_name("object")
                attr = func.child_by_field_name("attribute")
                if obj and attr:
                    receiver = obj.text.decode("utf-8")
                    method = attr.text.decode("utf-8")
                    if "stub" in receiver.lower():
                        caller = self._find_enclosing_function(node)
                        parts = caller.rsplit(".", 1)
                        movements.append(InteractionInfo(
                            source_class=parts[0] if len(parts) > 1 else "",
                            source_method=parts[-1],
                            target=f"{receiver}.{method}",
                            target_type="GRPC_SERVICE",
                            direction="REQUEST_RESPONSE",
                            mechanism="gRPC",
                            file=file_path,
                            line=node.start_point[0] + 1,
                            confidence=0.80,
                        ))
        for child in node.children:
            self._walk_python_grpc(child, file_path, movements)

    # --- Private: endpoint detection ---

    def _walk_endpoints(self, node: Node, file_path: str, endpoints: list[EndpointInfo]):
        """Walk decorated function definitions to find route decorators."""
        if node.type == "decorated_definition":
            self._check_decorated_endpoint(node, file_path, endpoints)

        for child in node.children:
