        receiver = None
        method = None

        if func.type == "attribute":
            obj = func.child_by_field_name("object")
            attr = func.child_by_field_name("attribute")
            if obj and attr:
                receiver = obj.text.decode("utf-8")
                method = attr.text.decode("utf-8")
        elif func.type == "identifier":
            method = func.text.decode("utf-8")

        if not method:
            return

        caller = self._find_enclosing_function(node)
        caller_parts = caller.rsplit(".", 1)
        source_class = caller_parts[0] if len(caller_parts) > 1 else ""
        source_method = caller_parts[-1]
        line = node.start_point[0] + 1

        for pat in patterns:
            if method not in pat.get("methods", []):
                continue

            pat_receiver = pat.get("receiver")
            pat_suffix = pat.get("receiver_suffix")
            pat_prefix = pat.get("receiver_prefix")

            matched = False
            if pat_receiver is None and receiver is None:
                matched = True
            elif pat_receiver and receiver and pat_receiver in receiver:
                matched = True
            elif pat_suffix and receiver and pat_suffix.lower() in receiver.lower():
                matched = True
            elif pat_prefix and receiver and receiver.startswith(pat_prefix):
                matched = True

            if matched:
                target = self._extract_first_string_arg(node) or f"{receiver or ''}.{method}"
                movements.append(InteractionInfo(
                    source_class=source_class,
                    source_method=source_method,
                    target=target,
                    target_type=pat.get("target_type", "UNKNOWN"),
                    direction=pat.get("direction", "REQUEST_RESPONSE"),
                    mechanism=pat.get("mechanism", ""),
                    file=file_path,
                    line=line,
                    confidence=0.80,
                ))
                break

    def _extract_first_string_arg(self, call_node: Node) -> str:
        """Extract the first string argument from a call."""
        args = call_node.child_by_field_name("arguments")
        if args:
            for arg in args.children:
                if arg.type == "string":
                    return arg.text.decode("utf-8").strip("\"'")
        return ""

    # --- Private methods ---

    def _walk(self, node: Node, file_path: str, calls: list[RawCallSite]):
        """Recursively walk AST to find call expressions."""
        if node.type == "call":
            call_site = self._extract_call(node, file_path)
            if call_site:
                calls.append(call_site)

        for child in node.children:
            self._walk(child, file_path, calls)

    def _extract_call(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        """Extract a RawCallSite from a call node."""
        func = node.child_by_field_name("function")
        if not func:
            return None

        caller_name = self._find_enclosing_function(node)
        line = node.start_point[0] + 1  # 1-indexed

        if func.type == "attribute":
            obj = func.child_by_field_name("object")
            attr = func.child_by_field_name("attribute")
            if obj and attr:
                return RawCallSite(
                    file_path=file_path,
                    caller_name=caller_name,
                    receiver=obj.text.decode("utf-8"),
                    method=attr.text.decode("utf-8"),
                    line=line,
                )
        elif func.type == "identifier":
            name = func.text.decode("utf-8")
            return RawCallSite(
                file_path=file_path,
                caller_name=caller_name,
                receiver=None,
                method=name,
                line=line,
            )

        return None

    def _find_enclosing_function(self, node: Node) -> str:
        """Walk up AST to find enclosing function/method name."""
        current = node.parent
        func_name = None
        class_name = None

        while current:
            if current.type == "function_definition" and func_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    func_name = name_node.text.decode("utf-8")

            if current.type == "class_definition" and class_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    class_name = name_node.text.decode("utf-8")

            current = current.parent

        if class_name and func_name:
            return f"{class_name}.{func_name}"
        elif func_name:
            return func_name
        return "<module>"

    def _walk_assignments(self, node: Node, class_name: Optional[str], result: dict):
        """Find self.x = ClassName() patterns."""
        if node.type == "class_definition":
            name_node = node.child_by_field_name("name")
            cn = name_node.text.decode("utf-8") if name_node else None
            for child in node.children:
                self._walk_assignments(child, cn, result)
            return

        if node.type == "assignment" and class_name:
            left = node.children[0] if node.children else None
            right = node.children[-1] if len(node.children) >= 3 else None

            if left and right and left.type == "attribute":
                obj = left.child_by_field_name("object")
                attr = left.child_by_field_name("attribute")
                if obj and attr and obj.text == b"self":
                    attr_name = attr.text.decode("utf-8")
                    resolved = self._resolve_rhs_class(right)
                    if resolved:
                        result[f"{class_name}.{attr_name}"] = resolved

        for child in node.children:
            self._walk_assignments(child, class_name, result)

    def _resolve_rhs_class(self, node: Node) -> Optional[str]:
        """If node is ClassName(), return ClassName."""
        if node.type == "call":
            func = node.child_by_field_name("function")
            if func and func.type == "identifier":
                name = func.text.decode("utf-8")
                if name[0].isupper():
                    return name
        return None

    def _walk_annotations(self, node: Node, class_name: Optional[str], result: dict):
        """Find type annotations on class attrs and function params."""
        if node.type == "class_definition":
            name_node = node.child_by_field_name("name")
            cn = name_node.text.decode("utf-8") if name_node else None
            for child in node.children:
                self._walk_annotations(child, cn, result)
            return

        if node.type == "expression_statement" and class_name:
            pass

        if node.type == "function_definition" and class_name:
            params = node.child_by_field_name("parameters")
            if params:
                for param in params.named_children:
                    if param.type == "typed_parameter":
                        name_node = param.children[0] if param.children else None
                        type_node = param.child_by_field_name("type")
                        if name_node and type_node:
                            param_name = name_node.text.decode("utf-8")
                            type_name = type_node.text.decode("utf-8")
                            if param_name != "self" and type_name[0].isupper():
                                result[f"{class_name}.{param_name}"] = type_name

        if node.type == "assignment" and class_name:
            left = node.children[0] if node.children else None
            if left and left.type == "type":
                pass

        for child in node.children:
            self._walk_annotations(child, class_name, result)

"""Java tree-sitter extractor.

Extracts calls, imports, assignments, and type annotations from Java ASTs.
Handles: method_invocation, object_creation_expression, import_declaration,
local_variable_declaration, field_declaration, class_declaration.
"""
from typing import Optional, Any

import tree_sitter_java as ts_java
from tree_sitter import Language, Parser, Node

from src.ast.treesitter_models import RawCallSite
from src.ast.extractors.base import LanguageExtractor
from src.ast.models import EndpointInfo, DataMovementInfo
from src.ast.extractors.endpoint_config import get_endpoint_frameworks, get_data_movement_patterns

JAVA_LANGUAGE = Language(ts_java.language())


class JavaExtractor(LanguageExtractor):
    """Extract call sites, imports, assignments, and annotations from Java source."""

    def __init__(self):
        self._parser = Parser(JAVA_LANGUAGE)

    @property
    def file_extensions(self) -> list[str]:
        return [".java"]

    @property
    def grammar(self) -> Any:
        return JAVA_LANGUAGE

    def extract_calls(self, source: bytes, file_path: str) -> list[RawCallSite]:
        tree = self._parser.parse(source)
        calls: list[RawCallSite] = []
        self._walk_calls(tree.root_node, file_path, calls)
        return calls

    def extract_imports(self, source: bytes) -> list[tuple[str, list[str], bool]]:
        tree = self._parser.parse(source)
        imports: list[tuple[str, list[str], bool]] = []

        for node in tree.root_node.children:
            if node.type != "import_declaration":
                continue
            # import java.util.List; or import java.util.*;
            text = node.text.decode("utf-8").strip().rstrip(";")
            # Remove "import " and optional "static "
            path = text.replace("import ", "").replace("static ", "").strip()
            if path.endswith(".*"):
                module = path[:-2]
                imports.append((module, ["*"], False))
            else:
                parts = path.rsplit(".", 1)
                module = parts[0] if len(parts) > 1 else path
                name = parts[1] if len(parts) > 1 else path
                imports.append((module, [name], False))

        return imports

    def extract_assignments(self, source: bytes) -> dict[str, str]:
        tree = self._parser.parse(source)
        assignments: dict[str, str] = {}
        self._walk_assignments(tree.root_node, None, assignments)
        return assignments

    def extract_annotations(self, source: bytes) -> dict[str, str]:
        tree = self._parser.parse(source)
        annotations: dict[str, str] = {}
        self._walk_annotations(tree.root_node, None, annotations)
        return annotations

    def extract_endpoints(self, source: bytes, file_path: str) -> list[EndpointInfo]:
        """Detect Spring annotations (@GetMapping, @PostMapping, etc.) on methods."""
        tree = self._parser.parse(source)
        endpoints: list[EndpointInfo] = []
        frameworks = get_endpoint_frameworks("java")
        self._walk_endpoint_annotations(tree.root_node, file_path, endpoints, frameworks, None)
        return endpoints

    def extract_data_movements(self, source: bytes, file_path: str) -> list[DataMovementInfo]:
        """Detect RestTemplate, JPA Repository, KafkaTemplate, gRPC stubs, etc."""
        tree = self._parser.parse(source)
        movements: list[DataMovementInfo] = []
        patterns = get_data_movement_patterns("java")
        self._walk_java_data_movements(tree.root_node, file_path, movements, patterns)

        # gRPC: if file imports io.grpc, match calls on *Stub/*BlockingStub receivers
        imports = self.extract_imports(source)
        has_grpc = any("io.grpc" in mod or "grpc" in mod for mod, _, _ in imports)
        if has_grpc:
            self._walk_java_grpc(tree.root_node, file_path, movements)

        return movements

    def _walk_java_grpc(self, node: Node, file_path: str, movements: list[DataMovementInfo]):
        """Detect gRPC stub calls: stub.hello(), blockingStub.getFeature()."""
        if node.type == "method_invocation":
            obj_node = node.child_by_field_name("object")
            name_node = node.child_by_field_name("name")
            if obj_node and name_node:
                receiver = obj_node.text.decode("utf-8")
                method = name_node.text.decode("utf-8")
                # Match receivers ending in Stub/BlockingStub/FutureStub
                is_stub = (receiver.lower().endswith("stub")
                           or "Stub" in receiver
                           or "stub" in receiver)
                # Skip gRPC infrastructure methods
                skip = {"withDeadlineAfter", "withCallCredentials", "withCompression",
                        "withInterceptors", "withMaxInboundMessageSize", "withWaitForReady"}
                if is_stub and method not in skip:
                    caller = self._find_enclosing_scope(node)
                    parts = caller.rsplit(".", 1)
                    movements.append(DataMovementInfo(
                        source_class=parts[0] if len(parts) > 1 else "",
                        source_method=parts[-1],
                        target=f"{receiver}.{method}",
                        target_type="GRPC_SERVICE",
                        direction="REQUEST_RESPONSE",
                        mechanism="gRPC",
                        file=file_path,
                        line=node.start_point[0] + 1,
                        confidence=0.80,
                    ))
        for child in node.children:
            self._walk_java_grpc(child, file_path, movements)

    # --- Endpoint detection ---

    def _walk_endpoint_annotations(self, node: Node, file_path: str,
                                    endpoints: list[EndpointInfo],
                                    frameworks: dict, class_name: Optional[str]):
        """Walk class/method declarations looking for endpoint annotations."""
        if node.type in ("class_declaration", "interface_declaration"):
            name = node.child_by_field_name("name")
            cls = name.text.decode("utf-8") if name else class_name
            for child in node.children:
                self._walk_endpoint_annotations(child, file_path, endpoints, frameworks, cls)
            return

        if node.type == "method_declaration":
            self._check_java_method_endpoint(node, file_path, endpoints, frameworks, class_name)

        for child in node.children:
            self._walk_endpoint_annotations(child, file_path, endpoints, frameworks, class_name)

    def _check_java_method_endpoint(self, node: Node, file_path: str,
                                     endpoints: list[EndpointInfo],
                                     frameworks: dict, class_name: Optional[str]):
        """Check if a method has endpoint annotations."""
        method_name = ""
        name_node = node.child_by_field_name("name")
        if name_node:
            method_name = name_node.text.decode("utf-8")

        line = node.start_point[0] + 1

        # Collect annotations (modifiers contain annotations in Java grammar)
        for child in node.children:
            if child.type == "modifiers":
                for mod in child.children:
                    if mod.type in ("annotation", "marker_annotation"):
                        ann_name = self._get_annotation_name(mod)
                        self._match_java_annotation(
                            ann_name, mod, file_path, class_name or "",
                            method_name, line, endpoints, frameworks
                        )

    def _get_annotation_name(self, annotation_node: Node) -> str:
        """Extract annotation name from @GetMapping or @GetMapping(...)."""
        for child in annotation_node.children:
            if child.type == "identifier":
                return child.text.decode("utf-8")
            if child.type == "scoped_identifier":
                return child.text.decode("utf-8").split(".")[-1]
        return ""

    def _match_java_annotation(self, ann_name: str, ann_node: Node,
                                file_path: str, class_name: str,
                                method_name: str, line: int,
                                endpoints: list[EndpointInfo], frameworks: dict):
        """Match an annotation name against configured framework patterns."""
        for fw_name, fw_config in frameworks.items():
            for pattern in fw_config.get("annotations", []):
                if ann_name == pattern["pattern"]:
                    path = self._extract_annotation_string_arg(ann_node)
                    op = pattern.get("operation", "DYNAMIC")
                    endpoints.append(EndpointInfo(
                        type=pattern.get("type", "REST"),
                        path=path,
                        operation=op,
                        handler_class=class_name,
                        handler_method=method_name,
                        file=file_path,
                        line=line,
                        direction="INBOUND",
                        protocol=pattern.get("protocol", "HTTP"),
                        framework=fw_name,
                        confidence=0.90,
                    ))
                    return

    def _extract_annotation_string_arg(self, annotation_node: Node) -> str:
        """Extract string value from annotation like @GetMapping('/path') or @GetMapping(value='/path')."""
        for child in annotation_node.children:
            if child.type == "annotation_argument_list":
                for arg in child.children:
                    if arg.type == "string_literal":
                        return arg.text.decode("utf-8").strip('"')
                    if arg.type == "element_value_pair":
                        for ev in arg.children:
                            if ev.type == "string_literal":
                                return ev.text.decode("utf-8").strip('"')
        return ""

    # --- Data movement detection ---

    def _walk_java_data_movements(self, node: Node, file_path: str,
                                   movements: list[DataMovementInfo], patterns: list[dict]):
        """Walk method invocations to find data movement patterns."""
        if node.type == "method_invocation":
            self._check_java_data_movement(node, file_path, movements, patterns)

        for child in node.children:
            self._walk_java_data_movements(child, file_path, movements, patterns)

    def _check_java_data_movement(self, node: Node, file_path: str,
                                   movements: list[DataMovementInfo], patterns: list[dict]):
        """Check if a method invocation matches a data movement pattern."""
        name_node = node.child_by_field_name("name")
        obj_node = node.child_by_field_name("object")
        if not name_node:
            return

        method = name_node.text.decode("utf-8")
        receiver = obj_node.text.decode("utf-8") if obj_node else None

        caller = self._find_enclosing_scope(node)
        caller_parts = caller.rsplit(".", 1)
        source_class = caller_parts[0] if len(caller_parts) > 1 else ""
        source_method = caller_parts[-1]
        line = node.start_point[0] + 1

        for pat in patterns:
            if method not in pat.get("methods", []):
                continue

            pat_receiver = pat.get("receiver")
            pat_suffix = pat.get("receiver_suffix")

            matched = False
            if pat_receiver and receiver and pat_receiver.lower() in receiver.lower():
                matched = True
            elif pat_suffix and receiver and pat_suffix.lower() in receiver.lower():
                matched = True

            if matched:
                target = self._extract_java_first_string_arg(node) or f"{receiver}.{method}"
                movements.append(DataMovementInfo(
                    source_class=source_class,
                    source_method=source_method,
                    target=target,
                    target_type=pat.get("target_type", "UNKNOWN"),
                    direction=pat.get("direction", "REQUEST_RESPONSE"),
                    mechanism=pat.get("mechanism", ""),
                    file=file_path,
                    line=line,
                    confidence=0.80,
                ))
                break

    def _extract_java_first_string_arg(self, node: Node) -> str:
        """Extract the first string argument from a method invocation."""
        args = node.child_by_field_name("arguments")
        if args:
            for arg in args.children:
                if arg.type == "string_literal":
                    return arg.text.decode("utf-8").strip('"')
        return ""

    # --- Call extraction ---

    def _walk_calls(self, node: Node, file_path: str, calls: list[RawCallSite]):
        if node.type == "method_invocation":
            call = self._extract_method_invocation(node, file_path)
            if call:
                calls.append(call)

        elif node.type == "object_creation_expression":
            call = self._extract_object_creation(node, file_path)
            if call:
                calls.append(call)

        for child in node.children:
            self._walk_calls(child, file_path, calls)

    def _extract_method_invocation(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        name_node = node.child_by_field_name("name")
        obj_node = node.child_by_field_name("object")
        if not name_node:
            return None

        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1
        method = name_node.text.decode("utf-8")
        receiver = obj_node.text.decode("utf-8") if obj_node else None

        return RawCallSite(
            file_path=file_path,
            caller_name=caller,
            receiver=receiver,
            method=method,
            line=line,
        )

    def _extract_object_creation(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        type_node = node.child_by_field_name("type")
        if not type_node:
            return None

        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1
        # Extract base type (strip generics)
        type_name = self._extract_base_type(type_node)

        return RawCallSite(
            file_path=file_path,
            caller_name=caller,
            receiver=None,
            method=f"new {type_name}",
            line=line,
        )

    def _find_enclosing_scope(self, node: Node) -> str:
        current = node.parent
        method_name = None
        class_name = None

        while current:
            if current.type == "method_declaration" and method_name is None:
                name = current.child_by_field_name("name")
                if name:
                    method_name = name.text.decode("utf-8")

            elif current.type == "constructor_declaration" and method_name is None:
                name = current.child_by_field_name("name")
                if name:
                    method_name = f"<init:{name.text.decode('utf-8')}>"

            elif current.type in ("class_declaration", "interface_declaration",
                                   "enum_declaration") and class_name is None:
                name = current.child_by_field_name("name")
                if name:
                    class_name = name.text.decode("utf-8")

            current = current.parent

        if class_name and method_name:
            return f"{class_name}.{method_name}"
        elif class_name:
            return class_name
        elif method_name:
            return method_name
        return "<module>"

    # --- Assignments ---

    def _walk_assignments(self, node: Node, scope: Optional[str], result: dict):
        if node.type in ("class_declaration", "interface_declaration", "enum_declaration"):
            name = node.child_by_field_name("name")
            cls = name.text.decode("utf-8") if name else scope
            for child in node.children:
                self._walk_assignments(child, cls, result)
            return

        if node.type == "method_declaration":
            name = node.child_by_field_name("name")
            fn = name.text.decode("utf-8") if name else None
            method_scope = f"{scope}.{fn}" if scope and fn else fn
            for child in node.children:
                self._walk_assignments(child, method_scope, result)
            return

        # List<String> items = new ArrayList<>(); or Database db = new Database();
        if node.type == "local_variable_declaration":
            type_name = self._extract_decl_type(node)
            declarator = node.child_by_field_name("declarator")
            if declarator and type_name:
                var_name = declarator.child_by_field_name("name")
                value = declarator.child_by_field_name("value")
                if var_name:
                    prefix = f"{scope}." if scope else ""
                    # Prefer RHS type for new expressions
                    rhs_type = self._resolve_rhs(value) if value else None
                    result[f"{prefix}{var_name.text.decode('utf-8')}"] = rhs_type or type_name

        if node.type == "field_declaration":
            type_name = self._extract_decl_type(node)
            declarator = node.child_by_field_name("declarator")
            if declarator and type_name:
                var_name = declarator.child_by_field_name("name")
                if var_name:
                    prefix = f"{scope}." if scope else ""
                    result[f"{prefix}{var_name.text.decode('utf-8')}"] = type_name

        for child in node.children:
            self._walk_assignments(child, scope, result)

    def _extract_decl_type(self, node: Node) -> Optional[str]:
        type_node = node.child_by_field_name("type")
        if type_node:
            return self._extract_base_type(type_node)
        return None

    def _resolve_rhs(self, node: Node) -> Optional[str]:
        if not node:
            return None
        if node.type == "object_creation_expression":
            type_node = node.child_by_field_name("type")
            if type_node:
                return self._extract_base_type(type_node)
        return None

    # --- Annotations (type info) ---

    def _walk_annotations(self, node: Node, scope: Optional[str], result: dict):
        if node.type in ("class_declaration", "interface_declaration", "enum_declaration"):
            name = node.child_by_field_name("name")
            cls = name.text.decode("utf-8") if name else scope
            for child in node.children:
                self._walk_annotations(child, cls, result)
            return

        if node.type == "method_declaration":
            name = node.child_by_field_name("name")
            fn = name.text.decode("utf-8") if name else None
            method_scope = f"{scope}.{fn}" if scope and fn else fn
            # Extract parameter types
            params = node.child_by_field_name("parameters")
            if params:
                for param in params.named_children:
                    if param.type == "formal_parameter":
                        ptype = param.child_by_field_name("type")
                        pname = param.child_by_field_name("name")
                        if ptype and pname:
                            prefix = f"{method_scope}." if method_scope else ""
                            result[f"{prefix}{pname.text.decode('utf-8')}"] = \
                                self._extract_base_type(ptype)
            for child in node.children:
                self._walk_annotations(child, method_scope, result)
            return

        for child in node.children:
            self._walk_annotations(child, scope, result)

    # --- Helpers ---

    def _extract_base_type(self, type_node: Node) -> str:
        """Extract base type name, stripping generics. List<String> → List."""
        if type_node.type == "generic_type":
            for child in type_node.children:
                if child.type == "type_identifier":
                    return child.text.decode("utf-8")
        if type_node.type == "type_identifier":
            return type_node.text.decode("utf-8")
        if type_node.type == "scoped_type_identifier":
            return type_node.text.decode("utf-8").replace(".", "_")
        return type_node.text.decode("utf-8").split("<")[0].split("[")[0]

"""Java tree-sitter extractor.

Extracts calls, imports, assignments, and type annotations from Java ASTs.
Handles: method_invocation, object_creation_expression, import_declaration,
local_variable_declaration, field_declaration, class_declaration.
"""
from typing import Optional, Any

import tree_sitter_java as ts_java
from tree_sitter import Language, Parser, Node

from src.ast.treesitter_models import RawCallSite
from src.ast.extractors.base import LanguageExtractor
from src.ast.models import EndpointInfo, InteractionInfo
from src.ast.extractors.endpoint_config import get_endpoint_frameworks, get_data_movement_patterns

JAVA_LANGUAGE = Language(ts_java.language())


class JavaExtractor(LanguageExtractor):
    """Extract call sites, imports, assignments, and annotations from Java source."""

    def __init__(self):
        self._parser = Parser(JAVA_LANGUAGE)

    @property
    def file_extensions(self) -> list[str]:
        return [".java"]

    @property
    def grammar(self) -> Any:
        return JAVA_LANGUAGE

    def extract_calls(self, source: bytes, file_path: str) -> list[RawCallSite]:
        tree = self._parser.parse(source)
        calls: list[RawCallSite] = []
        self._walk_calls(tree.root_node, file_path, calls)
        return calls

    def extract_imports(self, source: bytes) -> list[tuple[str, list[str], bool]]:
        tree = self._parser.parse(source)
        imports: list[tuple[str, list[str], bool]] = []

        for node in tree.root_node.children:
            if node.type != "import_declaration":
                continue
            # import java.util.List; or import java.util.*;
            text = node.text.decode("utf-8").strip().rstrip(";")
            # Remove "import " and optional "static "
            path = text.replace("import ", "").replace("static ", "").strip()
            if path.endswith(".*"):
                module = path[:-2]
                imports.append((module, ["*"], False))
            else:
                parts = path.rsplit(".", 1)
                module = parts[0] if len(parts) > 1 else path
                name = parts[1] if len(parts) > 1 else path
                imports.append((module, [name], False))

        return imports

    def extract_assignments(self, source: bytes) -> dict[str, str]:
        tree = self._parser.parse(source)
        assignments: dict[str, str] = {}
        self._walk_assignments(tree.root_node, None, assignments)
        return assignments

    def extract_annotations(self, source: bytes) -> dict[str, str]:
        tree = self._parser.parse(source)
        annotations: dict[str, str] = {}
        self._walk_annotations(tree.root_node, None, annotations)
        return annotations

    def extract_endpoints(self, source: bytes, file_path: str) -> list[EndpointInfo]:
        """Detect Spring annotations (@GetMapping, @PostMapping, etc.) on methods."""
        tree = self._parser.parse(source)
        endpoints: list[EndpointInfo] = []
        frameworks = get_endpoint_frameworks("java")
        self._walk_endpoint_annotations(tree.root_node, file_path, endpoints, frameworks, None)
        return endpoints

    def extract_data_movements(self, source: bytes, file_path: str) -> list[InteractionInfo]:
        """Detect RestTemplate, JPA Repository, KafkaTemplate, gRPC stubs, etc."""
        tree = self._parser.parse(source)
        movements: list[InteractionInfo] = []
        patterns = get_data_movement_patterns("java")
        self._walk_java_data_movements(tree.root_node, file_path, movements, patterns)

        # gRPC: if file imports io.grpc, match calls on *Stub/*BlockingStub receivers
        imports = self.extract_imports(source)
        has_grpc = any("io.grpc" in mod or "grpc" in mod for mod, _, _ in imports)
        if has_grpc:
            self._walk_java_grpc(tree.root_node, file_path, movements)

        return movements

    def _walk_java_grpc(self, node: Node, file_path: str, movements: list[InteractionInfo]):
        """Detect gRPC stub calls: stub.hello(), blockingStub.getFeature()."""
        if node.type == "method_invocation":
            obj_node = node.child_by_field_name("object")
            name_node = node.child_by_field_name("name")
            if obj_node and name_node:
                receiver = obj_node.text.decode("utf-8")
                method = name_node.text.decode("utf-8")
                # Match receivers ending in Stub/BlockingStub/FutureStub
                is_stub = (receiver.lower().endswith("stub")
                           or "Stub" in receiver
                           or "stub" in receiver)
                # Skip gRPC infrastructure methods
                skip = {"withDeadlineAfter", "withCallCredentials", "withCompression",
                        "withInterceptors", "withMaxInboundMessageSize", "withWaitForReady"}
                if is_stub and method not in skip:
                    caller = self._find_enclosing_scope(node)
                    parts = caller.rsplit(".", 1)
                    movements.append(InteractionInfo(
                        source_class=parts[0] if len(parts) > 1 else "",
                        source_method=parts[-1],
                        target=f"{receiver}.{method}",
                        target_type="GRPC_SERVICE",
                        direction="REQUEST_RESPONSE",
                        mechanism="gRPC",
                        file=file_path,
                        line=node.start_point[0] + 1,
                        confidence=0.80,
                    ))
        for child in node.children:
            self._walk_java_grpc(child, file_path, movements)

    # --- Endpoint detection ---

    def _walk_endpoint_annotations(self, node: Node, file_path: str,
                                    endpoints: list[EndpointInfo],
                                    frameworks: dict, class_name: Optional[str]):
        """Walk class/method declarations looking for endpoint annotations."""
        if node.type in ("class_declaration", "interface_declaration"):
            name = node.child_by_field_name("name")
            cls = name.text.decode("utf-8") if name else class_name
            for child in node.children:
                self._walk_endpoint_annotations(child, file_path, endpoints, frameworks, cls)
            return

        if node.type == "method_declaration":
            self._check_java_method_endpoint(node, file_path, endpoints, frameworks, class_name)

        for child in node.children:
            self._walk_endpoint_annotations(child, file_path, endpoints, frameworks, class_name)

    def _check_java_method_endpoint(self, node: Node, file_path: str,
                                     endpoints: list[EndpointInfo],
                                     frameworks: dict, class_name: Optional[str]):
        """Check if a method has endpoint annotations."""
        method_name = ""
        name_node = node.child_by_field_name("name")
        if name_node:
            method_name = name_node.text.decode("utf-8")

        line = node.start_point[0] + 1

        # Collect annotations (modifiers contain annotations in Java grammar)
        for child in node.children:
            if child.type == "modifiers":
                for mod in child.children:
                    if mod.type in ("annotation", "marker_annotation"):
                        ann_name = self._get_annotation_name(mod)
                        self._match_java_annotation(
                            ann_name, mod, file_path, class_name or "",
                            method_name, line, endpoints, frameworks
                        )

    def _get_annotation_name(self, annotation_node: Node) -> str:
        """Extract annotation name from @GetMapping or @GetMapping(...)."""
        for child in annotation_node.children:
            if child.type == "identifier":
                return child.text.decode("utf-8")
            if child.type == "scoped_identifier":
                return child.text.decode("utf-8").split(".")[-1]
        return ""

    def _match_java_annotation(self, ann_name: str, ann_node: Node,
                                file_path: str, class_name: str,
                                method_name: str, line: int,
                                endpoints: list[EndpointInfo], frameworks: dict):
        """Match an annotation name against configured framework patterns."""
        for fw_name, fw_config in frameworks.items():
            for pattern in fw_config.get("annotations", []):
                if ann_name == pattern["pattern"]:
                    path = self._extract_annotation_string_arg(ann_node)
                    op = pattern.get("operation", "DYNAMIC")
                    endpoints.append(EndpointInfo(
                        type=pattern.get("type", "REST"),
                        path=path,
                        operation=op,
                        handler_class=class_name,
                        handler_method=method_name,
                        file=file_path,
                        line=line,
                        direction="INBOUND",
                        protocol=pattern.get("protocol", "HTTP"),
                        framework=fw_name,
                        confidence=0.90,
                    ))
                    return

    def _extract_annotation_string_arg(self, annotation_node: Node) -> str:
        """Extract string value from annotation like @GetMapping('/path') or @GetMapping(value='/path')."""
        for child in annotation_node.children:
            if child.type == "annotation_argument_list":
                for arg in child.children:
                    if arg.type == "string_literal":
                        return arg.text.decode("utf-8").strip('"')
                    if arg.type == "element_value_pair":
                        for ev in arg.children:
                            if ev.type == "string_literal":
                                return ev.text.decode("utf-8").strip('"')
        return ""

    # --- Data movement detection ---

    def _walk_java_data_movements(self, node: Node, file_path: str,
                                   movements: list[InteractionInfo], patterns: list[dict]):
        """Walk method invocations to find data movement patterns."""
        if node.type == "method_invocation":
            self._check_java_data_movement(node, file_path, movements, patterns)

        for child in node.children:
            self._walk_java_data_movements(child, file_path, movements, patterns)

    def _check_java_data_movement(self, node: Node, file_path: str,
                                   movements: list[InteractionInfo], patterns: list[dict]):
        """Check if a method invocation matches a data movement pattern."""
        name_node = node.child_by_field_name("name")
        obj_node = node.child_by_field_name("object")
        if not name_node:
            return

        method = name_node.text.decode("utf-8")
        receiver = obj_node.text.decode("utf-8") if obj_node else None

        caller = self._find_enclosing_scope(node)
        caller_parts = caller.rsplit(".", 1)
        source_class = caller_parts[0] if len(caller_parts) > 1 else ""
        source_method = caller_parts[-1]
        line = node.start_point[0] + 1

        for pat in patterns:
            if method not in pat.get("methods", []):
                continue

            pat_receiver = pat.get("receiver")
            pat_suffix = pat.get("receiver_suffix")

            matched = False
            if pat_receiver and receiver and pat_receiver.lower() in receiver.lower():
                matched = True
            elif pat_suffix and receiver and pat_suffix.lower() in receiver.lower():
                matched = True

            if matched:
                target = self._extract_java_first_string_arg(node) or f"{receiver}.{method}"
                movements.append(InteractionInfo(
                    source_class=source_class,
                    source_method=source_method,
                    target=target,
                    target_type=pat.get("target_type", "UNKNOWN"),
                    direction=pat.get("direction", "REQUEST_RESPONSE"),
                    mechanism=pat.get("mechanism", ""),
                    file=file_path,
                    line=line,
                    confidence=0.80,
                ))
                break

    def _extract_java_first_string_arg(self, node: Node) -> str:
        """Extract the first string argument from a method invocation."""
        args = node.child_by_field_name("arguments")
        if args:
            for arg in args.children:
                if arg.type == "string_literal":
                    return arg.text.decode("utf-8").strip('"')
        return ""

    # --- Call extraction ---

    def _walk_calls(self, node: Node, file_path: str, calls: list[RawCallSite]):
        if node.type == "method_invocation":
            call = self._extract_method_invocation(node, file_path)
            if call:
                calls.append(call)

        elif node.type == "object_creation_expression":
            call = self._extract_object_creation(node, file_path)
            if call:
                calls.append(call)

        for child in node.children:
            self._walk_calls(child, file_path, calls)

    def _extract_method_invocation(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        name_node = node.child_by_field_name("name")
        obj_node = node.child_by_field_name("object")
        if not name_node:
            return None

        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1
        method = name_node.text.decode("utf-8")
        receiver = obj_node.text.decode("utf-8") if obj_node else None

        return RawCallSite(
            file_path=file_path,
            caller_name=caller,
            receiver=receiver,
            method=method,
            line=line,
        )

    def _extract_object_creation(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        type_node = node.child_by_field_name("type")
        if not type_node:
            return None

        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1
        # Extract base type (strip generics)
        type_name = self._extract_base_type(type_node)

        return RawCallSite(
            file_path=file_path,
            caller_name=caller,
            receiver=None,
            method=f"new {type_name}",
            line=line,
        )

    def _find_enclosing_scope(self, node: Node) -> str:
        current = node.parent
        method_name = None
        class_name = None

        while current:
            if current.type == "method_declaration" and method_name is None:
                name = current.child_by_field_name("name")
                if name:
                    method_name = name.text.decode("utf-8")

            elif current.type == "constructor_declaration" and method_name is None:
                name = current.child_by_field_name("name")
                if name:
                    method_name = f"<init:{name.text.decode('utf-8')}>"

            elif current.type in ("class_declaration", "interface_declaration",
                                   "enum_declaration") and class_name is None:
                name = current.child_by_field_name("name")
                if name:
                    class_name = name.text.decode("utf-8")

            current = current.parent

        if class_name and method_name:
            return f"{class_name}.{method_name}"
        elif class_name:
            return class_name
        elif method_name:
            return method_name
        return "<module>"

    # --- Assignments ---

    def _walk_assignments(self, node: Node, scope: Optional[str], result: dict):
        if node.type in ("class_declaration", "interface_declaration", "enum_declaration"):
            name = node.child_by_field_name("name")
            cls = name.text.decode("utf-8") if name else scope
            for child in node.children:
                self._walk_assignments(child, cls, result)
            return

        if node.type == "method_declaration":
            name = node.child_by_field_name("name")
            fn = name.text.decode("utf-8") if name else None
            method_scope = f"{scope}.{fn}" if scope and fn else fn
            for child in node.children:
                self._walk_assignments(child, method_scope, result)
            return

        # List<String> items = new ArrayList<>(); or Database db = new Database();
        if node.type == "local_variable_declaration":
            type_name = self._extract_decl_type(node)
            declarator = node.child_by_field_name("declarator")
            if declarator and type_name:
                var_name = declarator.child_by_field_name("name")
                value = declarator.child_by_field_name("value")
                if var_name:
                    prefix = f"{scope}." if scope else ""
                    # Prefer RHS type for new expressions
                    rhs_type = self._resolve_rhs(value) if value else None
                    result[f"{prefix}{var_name.text.decode('utf-8')}"] = rhs_type or type_name

        if node.type == "field_declaration":
            type_name = self._extract_decl_type(node)
            declarator = node.child_by_field_name("declarator")
            if declarator and type_name:
                var_name = declarator.child_by_field_name("name")
                if var_name:
                    prefix = f"{scope}." if scope else ""
                    result[f"{prefix}{var_name.text.decode('utf-8')}"] = type_name

        for child in node.children:
            self._walk_assignments(child, scope, result)

    def _extract_decl_type(self, node: Node) -> Optional[str]:
        type_node = node.child_by_field_name("type")
        if type_node:
            return self._extract_base_type(type_node)
        return None

    def _resolve_rhs(self, node: Node) -> Optional[str]:
        if not node:
            return None
        if node.type == "object_creation_expression":
            type_node = node.child_by_field_name("type")
            if type_node:
                return self._extract_base_type(type_node)
        return None

    # --- Annotations (type info) ---

    def _walk_annotations(self, node: Node, scope: Optional[str], result: dict):
        if node.type in ("class_declaration", "interface_declaration", "enum_declaration"):
            name = node.child_by_field_name("name")
            cls = name.text.decode("utf-8") if name else scope
            for child in node.children:
                self._walk_annotations(child, cls, result)
            return

        if node.type == "method_declaration":
            name = node.child_by_field_name("name")
            fn = name.text.decode("utf-8") if name else None
            method_scope = f"{scope}.{fn}" if scope and fn else fn
            # Extract parameter types
            params = node.child_by_field_name("parameters")
            if params:
                for param in params.named_children:
                    if param.type == "formal_parameter":
                        ptype = param.child_by_field_name("type")
                        pname = param.child_by_field_name("name")
                        if ptype and pname:
                            prefix = f"{method_scope}." if method_scope else ""
                            result[f"{prefix}{pname.text.decode('utf-8')}"] = \
                                self._extract_base_type(ptype)
            for child in node.children:
                self._walk_annotations(child, method_scope, result)
            return

        for child in node.children:
            self._walk_annotations(child, scope, result)

    # --- Helpers ---

    def _extract_base_type(self, type_node: Node) -> str:
        """Extract base type name, stripping generics. List<String> → List."""
        if type_node.type == "generic_type":
            for child in type_node.children:
                if child.type == "type_identifier":
                    return child.text.decode("utf-8")
        if type_node.type == "type_identifier":
            return type_node.text.decode("utf-8")
        if type_node.type == "scoped_type_identifier":
            return type_node.text.decode("utf-8").replace(".", "_")
        return type_node.text.decode("utf-8").split("<")[0].split("[")[0]

"""Java tree-sitter extractor.

Extracts calls, imports, assignments, and type annotations from Java ASTs.
Handles: method_invocation, object_creation_expression, import_declaration,
local_variable_declaration, field_declaration, class_declaration.
"""
from typing import Optional, Any

import tree_sitter_java as ts_java
from tree_sitter import Language, Parser, Node

from src.ast.treesitter_models import RawCallSite
from src.ast.extractors.base import LanguageExtractor
from src.ast.models import EndpointInfo, InteractionInfo
from src.ast.extractors.endpoint_config import get_endpoint_frameworks, get_interaction_patterns

JAVA_LANGUAGE = Language(ts_java.language())


class JavaExtractor(LanguageExtractor):
    """Extract call sites, imports, assignments, and annotations from Java source."""

    def __init__(self):
        self._parser = Parser(JAVA_LANGUAGE)

    @property
    def file_extensions(self) -> list[str]:
        return [".java"]

    @property
    def grammar(self) -> Any:
        return JAVA_LANGUAGE

    def extract_calls(self, source: bytes, file_path: str) -> list[RawCallSite]:
        tree = self._parser.parse(source)
        calls: list[RawCallSite] = []
        self._walk_calls(tree.root_node, file_path, calls)
        return calls

    def extract_imports(self, source: bytes) -> list[tuple[str, list[str], bool]]:
        tree = self._parser.parse(source)
        imports: list[tuple[str, list[str], bool]] = []

        for node in tree.root_node.children:
            if node.type != "import_declaration":
                continue
            # import java.util.List; or import java.util.*;
            text = node.text.decode("utf-8").strip().rstrip(";")
            # Remove "import " and optional "static "
            path = text.replace("import ", "").replace("static ", "").strip()
            if path.endswith(".*"):
                module = path[:-2]
                imports.append((module, ["*"], False))
            else:
                parts = path.rsplit(".", 1)
                module = parts[0] if len(parts) > 1 else path
                name = parts[1] if len(parts) > 1 else path
                imports.append((module, [name], False))

        return imports

    def extract_assignments(self, source: bytes) -> dict[str, str]:
        tree = self._parser.parse(source)
        assignments: dict[str, str] = {}
        self._walk_assignments(tree.root_node, None, assignments)
        return assignments

    def extract_annotations(self, source: bytes) -> dict[str, str]:
        tree = self._parser.parse(source)
        annotations: dict[str, str] = {}
        self._walk_annotations(tree.root_node, None, annotations)
        return annotations

    def extract_endpoints(self, source: bytes, file_path: str) -> list[EndpointInfo]:
        """Detect Spring annotations (@GetMapping, @PostMapping, etc.) on methods."""
        tree = self._parser.parse(source)
        endpoints: list[EndpointInfo] = []
        frameworks = get_endpoint_frameworks("java")
        self._walk_endpoint_annotations(tree.root_node, file_path, endpoints, frameworks, None)
        return endpoints

    def extract_data_movements(self, source: bytes, file_path: str) -> list[InteractionInfo]:
        """Detect RestTemplate, JPA Repository, KafkaTemplate, gRPC stubs, etc."""
        tree = self._parser.parse(source)
        movements: list[InteractionInfo] = []
        patterns = get_interaction_patterns("java")
        self._walk_java_data_movements(tree.root_node, file_path, movements, patterns)

        # gRPC: if file imports io.grpc, match calls on *Stub/*BlockingStub receivers
        imports = self.extract_imports(source)
        has_grpc = any("io.grpc" in mod or "grpc" in mod for mod, _, _ in imports)
        if has_grpc:
            self._walk_java_grpc(tree.root_node, file_path, movements)

        return movements

    def _walk_java_grpc(self, node: Node, file_path: str, movements: list[InteractionInfo]):
        """Detect gRPC stub calls: stub.hello(), blockingStub.getFeature()."""
        if node.type == "method_invocation":
            obj_node = node.child_by_field_name("object")
            name_node = node.child_by_field_name("name")
            if obj_node and name_node:
                receiver = obj_node.text.decode("utf-8")
                method = name_node.text.decode("utf-8")
                # Match receivers ending in Stub/BlockingStub/FutureStub
                is_stub = (receiver.lower().endswith("stub")
                           or "Stub" in receiver
                           or "stub" in receiver)
                # Skip gRPC infrastructure methods
                skip = {"withDeadlineAfter", "withCallCredentials", "withCompression",
                        "withInterceptors", "withMaxInboundMessageSize", "withWaitForReady"}
                if is_stub and method not in skip:
                    caller = self._find_enclosing_scope(node)
                    parts = caller.rsplit(".", 1)
                    movements.append(InteractionInfo(
                        source_class=parts[0] if len(parts) > 1 else "",
                        source_method=parts[-1],
                        target=f"{receiver}.{method}",
                        target_type="GRPC_SERVICE",
                        direction="REQUEST_RESPONSE",
                        mechanism="gRPC",
                        file=file_path,
                        line=node.start_point[0] + 1,
                        confidence=0.80,
                    ))
        for child in node.children:
            self._walk_java_grpc(child, file_path, movements)

    # --- Endpoint detection ---

    def _walk_endpoint_annotations(self, node: Node, file_path: str,
                                    endpoints: list[EndpointInfo],
                                    frameworks: dict, class_name: Optional[str]):
        """Walk class/method declarations looking for endpoint annotations."""
        if node.type in ("class_declaration", "interface_declaration"):
            name = node.child_by_field_name("name")
            cls = name.text.decode("utf-8") if name else class_name
            for child in node.children:
                self._walk_endpoint_annotations(child, file_path, endpoints, frameworks, cls)
            return

        if node.type == "method_declaration":
            self._check_java_method_endpoint(node, file_path, endpoints, frameworks, class_name)

        for child in node.children:
            self._walk_endpoint_annotations(child, file_path, endpoints, frameworks, class_name)

    def _check_java_method_endpoint(self, node: Node, file_path: str,
                                     endpoints: list[EndpointInfo],
                                     frameworks: dict, class_name: Optional[str]):
        """Check if a method has endpoint annotations."""
        method_name = ""
        name_node = node.child_by_field_name("name")
        if name_node:
            method_name = name_node.text.decode("utf-8")

        line = node.start_point[0] + 1

        # Collect annotations (modifiers contain annotations in Java grammar)
        for child in node.children:
            if child.type == "modifiers":
                for mod in child.children:
                    if mod.type in ("annotation", "marker_annotation"):
                        ann_name = self._get_annotation_name(mod)
                        self._match_java_annotation(
                            ann_name, mod, file_path, class_name or "",
                            method_name, line, endpoints, frameworks
                        )

    def _get_annotation_name(self, annotation_node: Node) -> str:
        """Extract annotation name from @GetMapping or @GetMapping(...)."""
        for child in annotation_node.children:
            if child.type == "identifier":
                return child.text.decode("utf-8")
            if child.type == "scoped_identifier":
                return child.text.decode("utf-8").split(".")[-1]
        return ""

    def _match_java_annotation(self, ann_name: str, ann_node: Node,
                                file_path: str, class_name: str,
                                method_name: str, line: int,
                                endpoints: list[EndpointInfo], frameworks: dict):
        """Match an annotation name against configured framework patterns."""
        for fw_name, fw_config in frameworks.items():
            for pattern in fw_config.get("annotations", []):
                if ann_name == pattern["pattern"]:
                    path = self._extract_annotation_string_arg(ann_node)
                    op = pattern.get("operation", "DYNAMIC")
                    endpoints.append(EndpointInfo(
                        type=pattern.get("type", "REST"),
                        path=path,
                        operation=op,
                        handler_class=class_name,
                        handler_method=method_name,
                        file=file_path,
                        line=line,
                        direction="INBOUND",
                        protocol=pattern.get("protocol", "HTTP"),
                        framework=fw_name,
                        confidence=0.90,
                    ))
                    return

    def _extract_annotation_string_arg(self, annotation_node: Node) -> str:
        """Extract string value from annotation like @GetMapping('/path') or @GetMapping(value='/path')."""
        for child in annotation_node.children:
            if child.type == "annotation_argument_list":
                for arg in child.children:
                    if arg.type == "string_literal":
                        return arg.text.decode("utf-8").strip('"')
                    if arg.type == "element_value_pair":
                        for ev in arg.children:
                            if ev.type == "string_literal":
                                return ev.text.decode("utf-8").strip('"')
        return ""

    # --- Data movement detection ---

    def _walk_java_data_movements(self, node: Node, file_path: str,
                                   movements: list[InteractionInfo], patterns: list[dict]):
        """Walk method invocations to find data movement patterns."""
        if node.type == "method_invocation":
            self._check_java_data_movement(node, file_path, movements, patterns)

        for child in node.children:
            self._walk_java_data_movements(child, file_path, movements, patterns)

    def _check_java_data_movement(self, node: Node, file_path: str,
                                   movements: list[InteractionInfo], patterns: list[dict]):
        """Check if a method invocation matches a data movement pattern."""
        name_node = node.child_by_field_name("name")
        obj_node = node.child_by_field_name("object")
        if not name_node:
            return

        method = name_node.text.decode("utf-8")
        receiver = obj_node.text.decode("utf-8") if obj_node else None

        caller = self._find_enclosing_scope(node)
        caller_parts = caller.rsplit(".", 1)
        source_class = caller_parts[0] if len(caller_parts) > 1 else ""
        source_method = caller_parts[-1]
        line = node.start_point[0] + 1

        for pat in patterns:
            if method not in pat.get("methods", []):
                continue

            pat_receiver = pat.get("receiver")
            pat_suffix = pat.get("receiver_suffix")

            matched = False
            if pat_receiver and receiver and pat_receiver.lower() in receiver.lower():
                matched = True
            elif pat_suffix and receiver and pat_suffix.lower() in receiver.lower():
                matched = True

            if matched:
                target = self._extract_java_first_string_arg(node) or f"{receiver}.{method}"
                movements.append(InteractionInfo(
                    source_class=source_class,
                    source_method=source_method,
                    target=target,
                    target_type=pat.get("target_type", "UNKNOWN"),
                    direction=pat.get("direction", "REQUEST_RESPONSE"),
                    mechanism=pat.get("mechanism", ""),
                    file=file_path,
                    line=line,
                    confidence=0.80,
                ))
                break

    def _extract_java_first_string_arg(self, node: Node) -> str:
        """Extract the first string argument from a method invocation."""
        args = node.child_by_field_name("arguments")
        if args:
            for arg in args.children:
                if arg.type == "string_literal":
                    return arg.text.decode("utf-8").strip('"')
        return ""

    # --- Call extraction ---

    def _walk_calls(self, node: Node, file_path: str, calls: list[RawCallSite]):
        if node.type == "method_invocation":
            call = self._extract_method_invocation(node, file_path)
            if call:
                calls.append(call)

        elif node.type == "object_creation_expression":
            call = self._extract_object_creation(node, file_path)
            if call:
                calls.append(call)

        for child in node.children:
            self._walk_calls(child, file_path, calls)

    def _extract_method_invocation(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        name_node = node.child_by_field_name("name")
        obj_node = node.child_by_field_name("object")
        if not name_node:
            return None

        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1
        method = name_node.text.decode("utf-8")
        receiver = obj_node.text.decode("utf-8") if obj_node else None

        return RawCallSite(
            file_path=file_path,
            caller_name=caller,
            receiver=receiver,
            method=method,
            line=line,
        )

    def _extract_object_creation(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        type_node = node.child_by_field_name("type")
        if not type_node:
            return None

        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1
        # Extract base type (strip generics)
        type_name = self._extract_base_type(type_node)

        return RawCallSite(
            file_path=file_path,
            caller_name=caller,
            receiver=None,
            method=f"new {type_name}",
            line=line,
        )

    def _find_enclosing_scope(self, node: Node) -> str:
        current = node.parent
        method_name = None
        class_name = None

        while current:
            if current.type == "method_declaration" and method_name is None:
                name = current.child_by_field_name("name")
                if name:
                    method_name = name.text.decode("utf-8")

            elif current.type == "constructor_declaration" and method_name is None:
                name = current.child_by_field_name("name")
                if name:
                    method_name = f"<init:{name.text.decode('utf-8')}>"

            elif current.type in ("class_declaration", "interface_declaration",
                                   "enum_declaration") and class_name is None:
                name = current.child_by_field_name("name")
                if name:
                    class_name = name.text.decode("utf-8")

            current = current.parent

        if class_name and method_name:
            return f"{class_name}.{method_name}"
        elif class_name:
            return class_name
        elif method_name:
            return method_name
        return "<module>"

    # --- Assignments ---

    def _walk_assignments(self, node: Node, scope: Optional[str], result: dict):
        if node.type in ("class_declaration", "interface_declaration", "enum_declaration"):
            name = node.child_by_field_name("name")
            cls = name.text.decode("utf-8") if name else scope
            for child in node.children:
                self._walk_assignments(child, cls, result)
            return

        if node.type == "method_declaration":
            name = node.child_by_field_name("name")
            fn = name.text.decode("utf-8") if name else None
            method_scope = f"{scope}.{fn}" if scope and fn else fn
            for child in node.children:
                self._walk_assignments(child, method_scope, result)
            return

        # List<String> items = new ArrayList<>(); or Database db = new Database();
        if node.type == "local_variable_declaration":
            type_name = self._extract_decl_type(node)
            declarator = node.child_by_field_name("declarator")
            if declarator and type_name:
                var_name = declarator.child_by_field_name("name")
                value = declarator.child_by_field_name("value")
                if var_name:
                    prefix = f"{scope}." if scope else ""
                    # Prefer RHS type for new expressions
                    rhs_type = self._resolve_rhs(value) if value else None
                    result[f"{prefix}{var_name.text.decode('utf-8')}"] = rhs_type or type_name

        if node.type == "field_declaration":
            type_name = self._extract_decl_type(node)
            declarator = node.child_by_field_name("declarator")
            if declarator and type_name:
                var_name = declarator.child_by_field_name("name")
                if var_name:
                    prefix = f"{scope}." if scope else ""
                    result[f"{prefix}{var_name.text.decode('utf-8')}"] = type_name

        for child in node.children:
            self._walk_assignments(child, scope, result)

    def _extract_decl_type(self, node: Node) -> Optional[str]:
        type_node = node.child_by_field_name("type")
        if type_node:
            return self._extract_base_type(type_node)
        return None

    def _resolve_rhs(self, node: Node) -> Optional[str]:
        if not node:
            return None
        if node.type == "object_creation_expression":
            type_node = node.child_by_field_name("type")
            if type_node:
                return self._extract_base_type(type_node)
        return None

    # --- Annotations (type info) ---

    def _walk_annotations(self, node: Node, scope: Optional[str], result: dict):
        if node.type in ("class_declaration", "interface_declaration", "enum_declaration"):
            name = node.child_by_field_name("name")
            cls = name.text.decode("utf-8") if name else scope
            for child in node.children:
                self._walk_annotations(child, cls, result)
            return

        if node.type == "method_declaration":
            name = node.child_by_field_name("name")
            fn = name.text.decode("utf-8") if name else None
            method_scope = f"{scope}.{fn}" if scope and fn else fn
            # Extract parameter types
            params = node.child_by_field_name("parameters")
            if params:
                for param in params.named_children:
                    if param.type == "formal_parameter":
                        ptype = param.child_by_field_name("type")
                        pname = param.child_by_field_name("name")
                        if ptype and pname:
                            prefix = f"{method_scope}." if method_scope else ""
                            result[f"{prefix}{pname.text.decode('utf-8')}"] = \
                                self._extract_base_type(ptype)
            for child in node.children:
                self._walk_annotations(child, method_scope, result)
            return

        for child in node.children:
            self._walk_annotations(child, scope, result)

    # --- Helpers ---

    def _extract_base_type(self, type_node: Node) -> str:
        """Extract base type name, stripping generics. List<String> → List."""
        if type_node.type == "generic_type":
            for child in type_node.children:
                if child.type == "type_identifier":
                    return child.text.decode("utf-8")
        if type_node.type == "type_identifier":
            return type_node.text.decode("utf-8")
        if type_node.type == "scoped_type_identifier":
            return type_node.text.decode("utf-8").replace(".", "_")
        return type_node.text.decode("utf-8").split("<")[0].split("[")[0]

"""TypeScript/JavaScript tree-sitter extractor.

Extracts calls, imports, assignments, and annotations from TypeScript/JavaScript ASTs.
Handles: call_expression, member_expression, new_expression, optional_chain_expression,
import_statement (named, default, namespace), variable_declaration, type_annotation.
"""
from typing import Optional, Any

import tree_sitter_typescript as ts_typescript
from tree_sitter import Language, Parser, Node

from src.ast.treesitter_models import RawCallSite
from src.ast.extractors.base import LanguageExtractor
from src.ast.models import EndpointInfo, DataMovementInfo
from src.ast.extractors.endpoint_config import get_endpoint_frameworks, get_data_movement_patterns

TS_LANGUAGE = Language(ts_typescript.language_typescript())
TSX_LANGUAGE = Language(ts_typescript.language_tsx())


class TypeScriptExtractor(LanguageExtractor):
    """Extract call sites, imports, assignments, and annotations from TypeScript/JS."""

    def __init__(self):
        self._ts_parser = Parser(TS_LANGUAGE)
        self._tsx_parser = Parser(TSX_LANGUAGE)

    @property
    def file_extensions(self) -> list[str]:
        return [".ts", ".tsx", ".js", ".jsx"]

    @property
    def grammar(self) -> Any:
        return TS_LANGUAGE

    def _parser_for(self, file_path: str = "") -> Parser:
        if file_path.endswith((".tsx", ".jsx")):
            return self._tsx_parser
        return self._ts_parser

    def extract_calls(self, source: bytes, file_path: str) -> list[RawCallSite]:
        """Extract all call expressions including new expressions and optional chains."""
        parser = self._parser_for(file_path)
        tree = parser.parse(source)
        calls: list[RawCallSite] = []
        self._walk_calls(tree.root_node, file_path, calls)
        return calls

    def extract_imports(self, source: bytes) -> list[tuple[str, list[str], bool]]:
        """Extract import statements.

        Handles:
        - import { A, B } from 'module'
        - import A from 'module'
        - import * as A from 'module'
        - import 'module' (side-effect)
        """
        tree = self._ts_parser.parse(source)
        imports: list[tuple[str, list[str], bool]] = []

        for node in tree.root_node.children:
            if node.type != "import_statement":
                continue

            module = None
            names: list[str] = []
            is_relative = False

            for child in node.children:
                if child.type == "string":
                    # Extract module path from string
                    module = self._string_value(child)
                    is_relative = module.startswith(".")

                elif child.type == "import_clause":
                    for clause_child in child.children:
                        if clause_child.type == "identifier":
                            # Default import: import X from '...'
                            names.append(clause_child.text.decode("utf-8"))

                        elif clause_child.type == "named_imports":
                            # Named imports: import { A, B } from '...'
                            for spec in clause_child.children:
                                if spec.type == "import_specifier":
                                    # Could be `A` or `A as B`
                                    name_node = spec.children[0] if spec.children else None
                                    if name_node:
                                        names.append(name_node.text.decode("utf-8"))

                        elif clause_child.type == "namespace_import":
                            # import * as X from '...'
                            for ns_child in clause_child.children:
                                if ns_child.type == "identifier":
                                    names.append(ns_child.text.decode("utf-8"))

            if module:
                if not names:
                    names = [module.split("/")[-1]]  # Side-effect import
                imports.append((module, names, is_relative))

        return imports

    def extract_assignments(self, source: bytes) -> dict[str, str]:
        """Extract assignments: const x = new Foo(), this.x = new Foo()."""
        tree = self._ts_parser.parse(source)
        assignments: dict[str, str] = {}
        self._walk_assignments(tree.root_node, None, assignments)
        return assignments

    def extract_annotations(self, source: bytes) -> dict[str, str]:
        """Extract type annotations from class methods and constructors."""
        tree = self._ts_parser.parse(source)
        annotations: dict[str, str] = {}
        self._walk_annotations(tree.root_node, None, annotations)
        return annotations

    def extract_endpoints(self, source: bytes, file_path: str) -> list[EndpointInfo]:
        """Detect Express router.get/app.post, NestJS decorators, Socket.IO."""
        parser = self._parser_for(file_path)
        tree = parser.parse(source)
        endpoints: list[EndpointInfo] = []
        frameworks = get_endpoint_frameworks("typescript")
        self._walk_ts_endpoints(tree.root_node, file_path, endpoints, frameworks)
        return endpoints

    def extract_data_movements(self, source: bytes, file_path: str) -> list[DataMovementInfo]:
        """Detect fetch, axios, Prisma, fs, redis, gRPC calls."""
        parser = self._parser_for(file_path)
        tree = parser.parse(source)
        movements: list[DataMovementInfo] = []
        patterns = get_data_movement_patterns("typescript")
        self._walk_ts_data_movements(tree.root_node, file_path, movements, patterns)

        # gRPC: if file imports @grpc, match calls on *Client receivers
        imports = self.extract_imports(source)
        has_grpc = any("grpc" in mod for mod, _, _ in imports)
        if has_grpc:
            self._walk_ts_grpc(tree.root_node, file_path, movements)

        return movements

    def _walk_ts_grpc(self, node: Node, file_path: str, movements: list[DataMovementInfo]):
        """Detect TypeScript gRPC client calls."""
        if node.type == "call_expression":
            func = node.child_by_field_name("function")
            if func and func.type == "member_expression":
                obj = func.child_by_field_name("object")
                prop = func.child_by_field_name("property")
                if obj and prop:
                    receiver = obj.text.decode("utf-8")
                    method = prop.text.decode("utf-8")
                    if "client" in receiver.lower() or "stub" in receiver.lower():
                        skip = {"close", "getChannel", "waitForReady"}
                        if method not in skip:
                            caller = self._find_enclosing_scope(node)
                            parts = caller.rsplit(".", 1)
                            movements.append(DataMovementInfo(
                                source_class=parts[0] if len(parts) > 1 else "",
                                source_method=parts[-1],
                                target=f"{receiver}.{method}",
                                target_type="GRPC_SERVICE",
                                direction="REQUEST_RESPONSE",
                                mechanism="gRPC",
                                file=file_path,
                                line=node.start_point[0] + 1,
                                confidence=0.75,
                            ))
        for child in node.children:
            self._walk_ts_grpc(child, file_path, movements)

    # --- Private: endpoint detection ---

    def _walk_ts_endpoints(self, node: Node, file_path: str,
                           endpoints: list[EndpointInfo], frameworks: dict):
        """Walk for Express-style call patterns: router.get('/path', handler)."""
        if node.type == "call_expression":
            self._check_ts_endpoint_call(node, file_path, endpoints, frameworks)

        for child in node.children:
            self._walk_ts_endpoints(child, file_path, endpoints, frameworks)

    def _check_ts_endpoint_call(self, node: Node, file_path: str,
                                 endpoints: list[EndpointInfo], frameworks: dict):
        """Check if a call matches an endpoint registration pattern."""
        func = node.child_by_field_name("function")
        if not func or func.type != "member_expression":
            return

        obj = func.child_by_field_name("object")
        prop = func.child_by_field_name("property")
        if not obj or not prop:
            return

        receiver = obj.text.decode("utf-8")
        method = prop.text.decode("utf-8")
        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1

        for fw_name, fw_config in frameworks.items():
            for pattern in fw_config.get("call_patterns", []):
                suffix = pattern.get("receiver_suffix", "")
                methods = pattern.get("methods", [])

                if method in methods and (not suffix or receiver.endswith(suffix)):
                    path = self._extract_ts_first_string_arg(node)
                    op = method.upper()
                    if pattern.get("type") == "WEBSOCKET":
                        op = "SUBSCRIBE"
                    endpoints.append(EndpointInfo(
                        type=pattern.get("type", "REST"),
                        path=path,
                        operation=op,
                        handler_class="",
                        handler_method=caller,
                        file=file_path,
                        line=line,
                        direction="INBOUND",
                        protocol=pattern.get("protocol", "HTTP"),
                        framework=fw_name,
                        confidence=0.85,
                    ))
                    return

    def _extract_ts_first_string_arg(self, call_node: Node) -> str:
        """Extract first string argument from a call."""
        args = call_node.child_by_field_name("arguments")
        if args:
            for arg in args.children:
                if arg.type == "string":
                    return self._string_value(arg)
                if arg.type == "template_string":
                    return arg.text.decode("utf-8").strip("`")
        return ""

    # --- Private: data movement detection ---

    def _walk_ts_data_movements(self, node: Node, file_path: str,
                                 movements: list[DataMovementInfo], patterns: list[dict]):
        if node.type == "call_expression":
            self._check_ts_data_movement(node, file_path, movements, patterns)

        for child in node.children:
            self._walk_ts_data_movements(child, file_path, movements, patterns)

    def _check_ts_data_movement(self, node: Node, file_path: str,
                                 movements: list[DataMovementInfo], patterns: list[dict]):
        func = node.child_by_field_name("function")
        if not func:
            return

        receiver = None
        method = None

        if func.type == "member_expression":
            obj = func.child_by_field_name("object")
            prop = func.child_by_field_name("property")
            if obj and prop:
                receiver = obj.text.decode("utf-8")
                method = prop.text.decode("utf-8")
        elif func.type == "identifier":
            method = func.text.decode("utf-8")

        if not method:
            return

        caller = self._find_enclosing_scope(node)
        caller_parts = caller.rsplit(".", 1)
        source_class = caller_parts[0] if len(caller_parts) > 1 else ""
        source_method = caller_parts[-1]
        line = node.start_point[0] + 1

        for pat in patterns:
            if method not in pat.get("methods", []):
                continue

            pat_receiver = pat.get("receiver")
            pat_suffix = pat.get("receiver_suffix")
            pat_prefix = pat.get("receiver_prefix")

            matched = False
            if pat_receiver is None and receiver is None:
                matched = True
            elif pat_receiver and receiver and pat_receiver in receiver:
                matched = True
            elif pat_suffix and receiver and pat_suffix.lower() in receiver.lower():
                matched = True
            elif pat_prefix and receiver and pat_prefix.lower() in receiver.lower():
                matched = True

            if matched:
                target = self._extract_ts_first_string_arg(node) or f"{receiver or ''}.{method}"
                movements.append(DataMovementInfo(
                    source_class=source_class,
                    source_method=source_method,
                    target=target,
                    target_type=pat.get("target_type", "UNKNOWN"),
                    direction=pat.get("direction", "REQUEST_RESPONSE"),
                    mechanism=pat.get("mechanism", ""),
                    file=file_path,
                    line=line,
                    confidence=0.80,
                ))
                break

    # --- Private: call extraction ---

    def _walk_calls(self, node: Node, file_path: str, calls: list[RawCallSite]):
        """Walk AST to find call_expression and new_expression nodes."""
        if node.type == "call_expression":
            call = self._extract_call(node, file_path)
            if call:
                calls.append(call)
        elif node.type == "new_expression":
            call = self._extract_new(node, file_path)
            if call:
                calls.append(call)

        for child in node.children:
            self._walk_calls(child, file_path, calls)

    def _extract_call(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        """Extract from call_expression: foo.bar(), func(), a?.b()."""
        func = node.child_by_field_name("function")
        if not func:
            return None

        caller_name = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1

        if func.type == "member_expression":
            obj = func.child_by_field_name("object")
            prop = func.child_by_field_name("property")
            if obj and prop:
                return RawCallSite(
                    file_path=file_path,
                    caller_name=caller_name,
                    receiver=obj.text.decode("utf-8"),
                    method=prop.text.decode("utf-8"),
                    line=line,
                )

        elif func.type == "identifier":
            name = func.text.decode("utf-8")
            return RawCallSite(
                file_path=file_path,
                caller_name=caller_name,
                receiver=None,
                method=name,
                line=line,
            )

        # Optional chaining: a?.b()
        elif func.type == "optional_chain_expression":
            # Drill into the chain
            return self._extract_optional_chain(func, file_path, caller_name, line)

        return None

    def _extract_new(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        """Extract from new_expression: new Foo()."""
        constructor = node.child_by_field_name("constructor")
        if not constructor:
            return None

        caller_name = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1
        name = constructor.text.decode("utf-8")

        return RawCallSite(
            file_path=file_path,
            caller_name=caller_name,
            receiver=None,
            method=name,
            line=line,
        )

    def _extract_optional_chain(
        self, node: Node, file_path: str, caller_name: str, line: int
    ) -> Optional[RawCallSite]:
        """Extract from optional chain: service?.findById()."""
        # Walk into the chain to find the member access
        for child in node.children:
            if child.type == "member_expression":
                obj = child.child_by_field_name("object")
                prop = child.child_by_field_name("property")
                if obj and prop:
                    return RawCallSite(
                        file_path=file_path,
                        caller_name=caller_name,
                        receiver=obj.text.decode("utf-8"),
                        method=prop.text.decode("utf-8"),
                        line=line,
                    )
        return None

    def _find_enclosing_scope(self, node: Node) -> str:
        """Walk up AST to find enclosing class.method or function name."""
        current = node.parent
        method_name = None
        class_name = None

        while current:
            if current.type == "method_definition" and method_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    method_name = name_node.text.decode("utf-8")

            elif current.type == "function_declaration" and method_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    method_name = name_node.text.decode("utf-8")

            elif current.type == "arrow_function" and method_name is None:
                # Check if assigned to a variable
                parent = current.parent
                if parent and parent.type == "variable_declarator":
                    name_node = parent.child_by_field_name("name")
                    if name_node:
                        method_name = name_node.text.decode("utf-8")

            elif current.type == "class_declaration" and class_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    class_name = name_node.text.decode("utf-8")

            current = current.parent

        if class_name and method_name:
            return f"{class_name}.{method_name}"
        elif method_name:
            return method_name
        return "<module>"

    # --- Private: assignments ---

    def _walk_assignments(self, node: Node, class_name: Optional[str], result: dict):
        """Find this.x = new Foo() and const x = new Foo() patterns."""
        if node.type == "class_declaration":
            name_node = node.child_by_field_name("name")
            cn = name_node.text.decode("utf-8") if name_node else None
            for child in node.children:
                self._walk_assignments(child, cn, result)
            return

        # this.x = new Foo() in constructor/method
        if node.type == "assignment_expression" and class_name:
            left = node.child_by_field_name("left")
            right = node.child_by_field_name("right")
            if left and right and left.type == "member_expression":
                obj = left.child_by_field_name("object")
                prop = left.child_by_field_name("property")
                if obj and prop and obj.text == b"this":
                    attr_name = prop.text.decode("utf-8")
                    resolved = self._resolve_rhs(right)
                    if resolved:
                        result[f"{class_name}.{attr_name}"] = resolved

        # const x = new Foo() / let x = new Foo()
        if node.type == "variable_declarator":
            name_node = node.child_by_field_name("name")
            value_node = node.child_by_field_name("value")
            if name_node and value_node:
                resolved = self._resolve_rhs(value_node)
                if resolved:
                    prefix = f"{class_name}." if class_name else ""
                    result[f"{prefix}{name_node.text.decode('utf-8')}"] = resolved

        for child in node.children:
            self._walk_assignments(child, class_name, result)

    def _resolve_rhs(self, node: Node) -> Optional[str]:
        """If node is new ClassName(), return ClassName."""
        if node.type == "new_expression":
            constructor = node.child_by_field_name("constructor")
            if constructor and constructor.type == "identifier":
                return constructor.text.decode("utf-8")
        return None

    # --- Private: annotations ---

    def _walk_annotations(self, node: Node, class_name: Optional[str], result: dict):
        """Extract type annotations from parameters."""
        if node.type == "class_declaration":
            name_node = node.child_by_field_name("name")
            cn = name_node.text.decode("utf-8") if name_node else None
            for child in node.children:
                self._walk_annotations(child, cn, result)
            return

        if node.type in ("method_definition", "function_declaration") and class_name:
            params = node.child_by_field_name("parameters")
            if params:
                for param in params.named_children:
                    if param.type == "required_parameter":
                        name_node = param.child_by_field_name("pattern")
                        type_node = param.child_by_field_name("type")
                        if name_node and type_node:
                            param_name = name_node.text.decode("utf-8")
                            type_text = type_node.text.decode("utf-8")
                            # Strip leading ': '
                            type_name = type_text.lstrip(": ").split("<")[0].strip()
                            if param_name != "this" and type_name[0:1].isupper():
                                result[f"{class_name}.{param_name}"] = type_name

        for child in node.children:
            self._walk_annotations(child, class_name, result)

    # --- Helpers ---

    @staticmethod
    def _string_value(node: Node) -> str:
        """Extract string content from a string node (strip quotes)."""
        text = node.text.decode("utf-8")
        if (text.startswith("'") and text.endswith("'")) or \
           (text.startswith('"') and text.endswith('"')):
            return text[1:-1]
        return text

"""TypeScript/JavaScript tree-sitter extractor.

Extracts calls, imports, assignments, and annotations from TypeScript/JavaScript ASTs.
Handles: call_expression, member_expression, new_expression, optional_chain_expression,
import_statement (named, default, namespace), variable_declaration, type_annotation.
"""
from typing import Optional, Any

import tree_sitter_typescript as ts_typescript
from tree_sitter import Language, Parser, Node

from src.ast.treesitter_models import RawCallSite
from src.ast.extractors.base import LanguageExtractor
from src.ast.models import EndpointInfo, InteractionInfo
from src.ast.extractors.endpoint_config import get_endpoint_frameworks, get_data_movement_patterns

TS_LANGUAGE = Language(ts_typescript.language_typescript())
TSX_LANGUAGE = Language(ts_typescript.language_tsx())


class TypeScriptExtractor(LanguageExtractor):
    """Extract call sites, imports, assignments, and annotations from TypeScript/JS."""

    def __init__(self):
        self._ts_parser = Parser(TS_LANGUAGE)
        self._tsx_parser = Parser(TSX_LANGUAGE)

    @property
    def file_extensions(self) -> list[str]:
        return [".ts", ".tsx", ".js", ".jsx"]

    @property
    def grammar(self) -> Any:
        return TS_LANGUAGE

    def _parser_for(self, file_path: str = "") -> Parser:
        if file_path.endswith((".tsx", ".jsx")):
            return self._tsx_parser
        return self._ts_parser

    def extract_calls(self, source: bytes, file_path: str) -> list[RawCallSite]:
        """Extract all call expressions including new expressions and optional chains."""
        parser = self._parser_for(file_path)
        tree = parser.parse(source)
        calls: list[RawCallSite] = []
        self._walk_calls(tree.root_node, file_path, calls)
        return calls

    def extract_imports(self, source: bytes) -> list[tuple[str, list[str], bool]]:
        """Extract import statements.

        Handles:
        - import { A, B } from 'module'
        - import A from 'module'
        - import * as A from 'module'
        - import 'module' (side-effect)
        """
        tree = self._ts_parser.parse(source)
        imports: list[tuple[str, list[str], bool]] = []

        for node in tree.root_node.children:
            if node.type != "import_statement":
                continue

            module = None
            names: list[str] = []
            is_relative = False

            for child in node.children:
                if child.type == "string":
                    # Extract module path from string
                    module = self._string_value(child)
                    is_relative = module.startswith(".")

                elif child.type == "import_clause":
                    for clause_child in child.children:
                        if clause_child.type == "identifier":
                            # Default import: import X from '...'
                            names.append(clause_child.text.decode("utf-8"))

                        elif clause_child.type == "named_imports":
                            # Named imports: import { A, B } from '...'
                            for spec in clause_child.children:
                                if spec.type == "import_specifier":
                                    # Could be `A` or `A as B`
                                    name_node = spec.children[0] if spec.children else None
                                    if name_node:
                                        names.append(name_node.text.decode("utf-8"))

                        elif clause_child.type == "namespace_import":
                            # import * as X from '...'
                            for ns_child in clause_child.children:
                                if ns_child.type == "identifier":
                                    names.append(ns_child.text.decode("utf-8"))

            if module:
                if not names:
                    names = [module.split("/")[-1]]  # Side-effect import
                imports.append((module, names, is_relative))

        return imports

    def extract_assignments(self, source: bytes) -> dict[str, str]:
        """Extract assignments: const x = new Foo(), this.x = new Foo()."""
        tree = self._ts_parser.parse(source)
        assignments: dict[str, str] = {}
        self._walk_assignments(tree.root_node, None, assignments)
        return assignments

    def extract_annotations(self, source: bytes) -> dict[str, str]:
        """Extract type annotations from class methods and constructors."""
        tree = self._ts_parser.parse(source)
        annotations: dict[str, str] = {}
        self._walk_annotations(tree.root_node, None, annotations)
        return annotations

    def extract_endpoints(self, source: bytes, file_path: str) -> list[EndpointInfo]:
        """Detect Express router.get/app.post, NestJS decorators, Socket.IO."""
        parser = self._parser_for(file_path)
        tree = parser.parse(source)
        endpoints: list[EndpointInfo] = []
        frameworks = get_endpoint_frameworks("typescript")
        self._walk_ts_endpoints(tree.root_node, file_path, endpoints, frameworks)
        return endpoints

    def extract_data_movements(self, source: bytes, file_path: str) -> list[InteractionInfo]:
        """Detect fetch, axios, Prisma, fs, redis, gRPC calls."""
        parser = self._parser_for(file_path)
        tree = parser.parse(source)
        movements: list[InteractionInfo] = []
        patterns = get_data_movement_patterns("typescript")
        self._walk_ts_data_movements(tree.root_node, file_path, movements, patterns)

        # gRPC: if file imports @grpc, match calls on *Client receivers
        imports = self.extract_imports(source)
        has_grpc = any("grpc" in mod for mod, _, _ in imports)
        if has_grpc:
            self._walk_ts_grpc(tree.root_node, file_path, movements)

        return movements

    def _walk_ts_grpc(self, node: Node, file_path: str, movements: list[InteractionInfo]):
        """Detect TypeScript gRPC client calls."""
        if node.type == "call_expression":
            func = node.child_by_field_name("function")
            if func and func.type == "member_expression":
                obj = func.child_by_field_name("object")
                prop = func.child_by_field_name("property")
                if obj and prop:
                    receiver = obj.text.decode("utf-8")
                    method = prop.text.decode("utf-8")
                    if "client" in receiver.lower() or "stub" in receiver.lower():
                        skip = {"close", "getChannel", "waitForReady"}
                        if method not in skip:
                            caller = self._find_enclosing_scope(node)
                            parts = caller.rsplit(".", 1)
                            movements.append(InteractionInfo(
                                source_class=parts[0] if len(parts) > 1 else "",
                                source_method=parts[-1],
                                target=f"{receiver}.{method}",
                                target_type="GRPC_SERVICE",
                                direction="REQUEST_RESPONSE",
                                mechanism="gRPC",
                                file=file_path,
                                line=node.start_point[0] + 1,
                                confidence=0.75,
                            ))
        for child in node.children:
            self._walk_ts_grpc(child, file_path, movements)

    # --- Private: endpoint detection ---

    def _walk_ts_endpoints(self, node: Node, file_path: str,
                           endpoints: list[EndpointInfo], frameworks: dict):
        """Walk for Express-style call patterns: router.get('/path', handler)."""
        if node.type == "call_expression":
            self._check_ts_endpoint_call(node, file_path, endpoints, frameworks)

        for child in node.children:
            self._walk_ts_endpoints(child, file_path, endpoints, frameworks)

    def _check_ts_endpoint_call(self, node: Node, file_path: str,
                                 endpoints: list[EndpointInfo], frameworks: dict):
        """Check if a call matches an endpoint registration pattern."""
        func = node.child_by_field_name("function")
        if not func or func.type != "member_expression":
            return

        obj = func.child_by_field_name("object")
        prop = func.child_by_field_name("property")
        if not obj or not prop:
            return

        receiver = obj.text.decode("utf-8")
        method = prop.text.decode("utf-8")
        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1

        for fw_name, fw_config in frameworks.items():
            for pattern in fw_config.get("call_patterns", []):
                suffix = pattern.get("receiver_suffix", "")
                methods = pattern.get("methods", [])

                if method in methods and (not suffix or receiver.endswith(suffix)):
                    path = self._extract_ts_first_string_arg(node)
                    op = method.upper()
                    if pattern.get("type") == "WEBSOCKET":
                        op = "SUBSCRIBE"
                    endpoints.append(EndpointInfo(
                        type=pattern.get("type", "REST"),
                        path=path,
                        operation=op,
                        handler_class="",
                        handler_method=caller,
                        file=file_path,
                        line=line,
                        direction="INBOUND",
                        protocol=pattern.get("protocol", "HTTP"),
                        framework=fw_name,
                        confidence=0.85,
                    ))
                    return

    def _extract_ts_first_string_arg(self, call_node: Node) -> str:
        """Extract first string argument from a call."""
        args = call_node.child_by_field_name("arguments")
        if args:
            for arg in args.children:
                if arg.type == "string":
                    return self._string_value(arg)
                if arg.type == "template_string":
                    return arg.text.decode("utf-8").strip("`")
        return ""

    # --- Private: data movement detection ---

    def _walk_ts_data_movements(self, node: Node, file_path: str,
                                 movements: list[InteractionInfo], patterns: list[dict]):
        if node.type == "call_expression":
            self._check_ts_data_movement(node, file_path, movements, patterns)

        for child in node.children:
            self._walk_ts_data_movements(child, file_path, movements, patterns)

    def _check_ts_data_movement(self, node: Node, file_path: str,
                                 movements: list[InteractionInfo], patterns: list[dict]):
        func = node.child_by_field_name("function")
        if not func:
            return

        receiver = None
        method = None

        if func.type == "member_expression":
            obj = func.child_by_field_name("object")
            prop = func.child_by_field_name("property")
            if obj and prop:
                receiver = obj.text.decode("utf-8")
                method = prop.text.decode("utf-8")
        elif func.type == "identifier":
            method = func.text.decode("utf-8")

        if not method:
            return

        caller = self._find_enclosing_scope(node)
        caller_parts = caller.rsplit(".", 1)
        source_class = caller_parts[0] if len(caller_parts) > 1 else ""
        source_method = caller_parts[-1]
        line = node.start_point[0] + 1

        for pat in patterns:
            if method not in pat.get("methods", []):
                continue

            pat_receiver = pat.get("receiver")
            pat_suffix = pat.get("receiver_suffix")
            pat_prefix = pat.get("receiver_prefix")

            matched = False
            if pat_receiver is None and receiver is None:
                matched = True
            elif pat_receiver and receiver and pat_receiver in receiver:
                matched = True
            elif pat_suffix and receiver and pat_suffix.lower() in receiver.lower():
                matched = True
            elif pat_prefix and receiver and pat_prefix.lower() in receiver.lower():
                matched = True

            if matched:
                target = self._extract_ts_first_string_arg(node) or f"{receiver or ''}.{method}"
                movements.append(InteractionInfo(
                    source_class=source_class,
                    source_method=source_method,
                    target=target,
                    target_type=pat.get("target_type", "UNKNOWN"),
                    direction=pat.get("direction", "REQUEST_RESPONSE"),
                    mechanism=pat.get("mechanism", ""),
                    file=file_path,
                    line=line,
                    confidence=0.80,
                ))
                break

    # --- Private: call extraction ---

    def _walk_calls(self, node: Node, file_path: str, calls: list[RawCallSite]):
        """Walk AST to find call_expression and new_expression nodes."""
        if node.type == "call_expression":
            call = self._extract_call(node, file_path)
            if call:
                calls.append(call)
        elif node.type == "new_expression":
            call = self._extract_new(node, file_path)
            if call:
                calls.append(call)

        for child in node.children:
            self._walk_calls(child, file_path, calls)

    def _extract_call(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        """Extract from call_expression: foo.bar(), func(), a?.b()."""
        func = node.child_by_field_name("function")
        if not func:
            return None

        caller_name = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1

        if func.type == "member_expression":
            obj = func.child_by_field_name("object")
            prop = func.child_by_field_name("property")
            if obj and prop:
                return RawCallSite(
                    file_path=file_path,
                    caller_name=caller_name,
                    receiver=obj.text.decode("utf-8"),
                    method=prop.text.decode("utf-8"),
                    line=line,
                )

        elif func.type == "identifier":
            name = func.text.decode("utf-8")
            return RawCallSite(
                file_path=file_path,
                caller_name=caller_name,
                receiver=None,
                method=name,
                line=line,
            )

        # Optional chaining: a?.b()
        elif func.type == "optional_chain_expression":
            # Drill into the chain
            return self._extract_optional_chain(func, file_path, caller_name, line)

        return None

    def _extract_new(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        """Extract from new_expression: new Foo()."""
        constructor = node.child_by_field_name("constructor")
        if not constructor:
            return None

        caller_name = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1
        name = constructor.text.decode("utf-8")

        return RawCallSite(
            file_path=file_path,
            caller_name=caller_name,
            receiver=None,
            method=name,
            line=line,
        )

    def _extract_optional_chain(
        self, node: Node, file_path: str, caller_name: str, line: int
    ) -> Optional[RawCallSite]:
        """Extract from optional chain: service?.findById()."""
        # Walk into the chain to find the member access
        for child in node.children:
            if child.type == "member_expression":
                obj = child.child_by_field_name("object")
                prop = child.child_by_field_name("property")
                if obj and prop:
                    return RawCallSite(
                        file_path=file_path,
                        caller_name=caller_name,
                        receiver=obj.text.decode("utf-8"),
                        method=prop.text.decode("utf-8"),
                        line=line,
                    )
        return None

    def _find_enclosing_scope(self, node: Node) -> str:
        """Walk up AST to find enclosing class.method or function name."""
        current = node.parent
        method_name = None
        class_name = None

        while current:
            if current.type == "method_definition" and method_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    method_name = name_node.text.decode("utf-8")

            elif current.type == "function_declaration" and method_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    method_name = name_node.text.decode("utf-8")

            elif current.type == "arrow_function" and method_name is None:
                # Check if assigned to a variable
                parent = current.parent
                if parent and parent.type == "variable_declarator":
                    name_node = parent.child_by_field_name("name")
                    if name_node:
                        method_name = name_node.text.decode("utf-8")

            elif current.type == "class_declaration" and class_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    class_name = name_node.text.decode("utf-8")

            current = current.parent

        if class_name and method_name:
            return f"{class_name}.{method_name}"
        elif method_name:
            return method_name
        return "<module>"

    # --- Private: assignments ---

    def _walk_assignments(self, node: Node, class_name: Optional[str], result: dict):
        """Find this.x = new Foo() and const x = new Foo() patterns."""
        if node.type == "class_declaration":
            name_node = node.child_by_field_name("name")
            cn = name_node.text.decode("utf-8") if name_node else None
            for child in node.children:
                self._walk_assignments(child, cn, result)
            return

        # this.x = new Foo() in constructor/method
        if node.type == "assignment_expression" and class_name:
            left = node.child_by_field_name("left")
            right = node.child_by_field_name("right")
            if left and right and left.type == "member_expression":
                obj = left.child_by_field_name("object")
                prop = left.child_by_field_name("property")
                if obj and prop and obj.text == b"this":
                    attr_name = prop.text.decode("utf-8")
                    resolved = self._resolve_rhs(right)
                    if resolved:
                        result[f"{class_name}.{attr_name}"] = resolved

        # const x = new Foo() / let x = new Foo()
        if node.type == "variable_declarator":
            name_node = node.child_by_field_name("name")
            value_node = node.child_by_field_name("value")
            if name_node and value_node:
                resolved = self._resolve_rhs(value_node)
                if resolved:
                    prefix = f"{class_name}." if class_name else ""
                    result[f"{prefix}{name_node.text.decode('utf-8')}"] = resolved

        for child in node.children:
            self._walk_assignments(child, class_name, result)

    def _resolve_rhs(self, node: Node) -> Optional[str]:
        """If node is new ClassName(), return ClassName."""
        if node.type == "new_expression":
            constructor = node.child_by_field_name("constructor")
            if constructor and constructor.type == "identifier":
                return constructor.text.decode("utf-8")
        return None

    # --- Private: annotations ---

    def _walk_annotations(self, node: Node, class_name: Optional[str], result: dict):
        """Extract type annotations from parameters."""
        if node.type == "class_declaration":
            name_node = node.child_by_field_name("name")
            cn = name_node.text.decode("utf-8") if name_node else None
            for child in node.children:
                self._walk_annotations(child, cn, result)
            return

        if node.type in ("method_definition", "function_declaration") and class_name:
            params = node.child_by_field_name("parameters")
            if params:
                for param in params.named_children:
                    if param.type == "required_parameter":
                        name_node = param.child_by_field_name("pattern")
                        type_node = param.child_by_field_name("type")
                        if name_node and type_node:
                            param_name = name_node.text.decode("utf-8")
                            type_text = type_node.text.decode("utf-8")
                            # Strip leading ': '
                            type_name = type_text.lstrip(": ").split("<")[0].strip()
                            if param_name != "this" and type_name[0:1].isupper():
                                result[f"{class_name}.{param_name}"] = type_name

        for child in node.children:
            self._walk_annotations(child, class_name, result)

    # --- Helpers ---

    @staticmethod
    def _string_value(node: Node) -> str:
        """Extract string content from a string node (strip quotes)."""
        text = node.text.decode("utf-8")
        if (text.startswith("'") and text.endswith("'")) or \
           (text.startswith('"') and text.endswith('"')):
            return text[1:-1]
        return text

"""TypeScript/JavaScript tree-sitter extractor.

Extracts calls, imports, assignments, and annotations from TypeScript/JavaScript ASTs.
Handles: call_expression, member_expression, new_expression, optional_chain_expression,
import_statement (named, default, namespace), variable_declaration, type_annotation.
"""
from typing import Optional, Any

import tree_sitter_typescript as ts_typescript
from tree_sitter import Language, Parser, Node

from src.ast.treesitter_models import RawCallSite
from src.ast.extractors.base import LanguageExtractor
from src.ast.models import EndpointInfo, InteractionInfo
from src.ast.extractors.endpoint_config import get_endpoint_frameworks, get_interaction_patterns

TS_LANGUAGE = Language(ts_typescript.language_typescript())
TSX_LANGUAGE = Language(ts_typescript.language_tsx())


class TypeScriptExtractor(LanguageExtractor):
    """Extract call sites, imports, assignments, and annotations from TypeScript/JS."""

    def __init__(self):
        self._ts_parser = Parser(TS_LANGUAGE)
        self._tsx_parser = Parser(TSX_LANGUAGE)

    @property
    def file_extensions(self) -> list[str]:
        return [".ts", ".tsx", ".js", ".jsx"]

    @property
    def grammar(self) -> Any:
        return TS_LANGUAGE

    def _parser_for(self, file_path: str = "") -> Parser:
        if file_path.endswith((".tsx", ".jsx")):
            return self._tsx_parser
        return self._ts_parser

    def extract_calls(self, source: bytes, file_path: str) -> list[RawCallSite]:
        """Extract all call expressions including new expressions and optional chains."""
        parser = self._parser_for(file_path)
        tree = parser.parse(source)
        calls: list[RawCallSite] = []
        self._walk_calls(tree.root_node, file_path, calls)
        return calls

    def extract_imports(self, source: bytes) -> list[tuple[str, list[str], bool]]:
        """Extract import statements.

        Handles:
        - import { A, B } from 'module'
        - import A from 'module'
        - import * as A from 'module'
        - import 'module' (side-effect)
        """
        tree = self._ts_parser.parse(source)
        imports: list[tuple[str, list[str], bool]] = []

        for node in tree.root_node.children:
            if node.type != "import_statement":
                continue

            module = None
            names: list[str] = []
            is_relative = False

            for child in node.children:
                if child.type == "string":
                    # Extract module path from string
                    module = self._string_value(child)
                    is_relative = module.startswith(".")

                elif child.type == "import_clause":
                    for clause_child in child.children:
                        if clause_child.type == "identifier":
                            # Default import: import X from '...'
                            names.append(clause_child.text.decode("utf-8"))

                        elif clause_child.type == "named_imports":
                            # Named imports: import { A, B } from '...'
                            for spec in clause_child.children:
                                if spec.type == "import_specifier":
                                    # Could be `A` or `A as B`
                                    name_node = spec.children[0] if spec.children else None
                                    if name_node:
                                        names.append(name_node.text.decode("utf-8"))

                        elif clause_child.type == "namespace_import":
                            # import * as X from '...'
                            for ns_child in clause_child.children:
                                if ns_child.type == "identifier":
                                    names.append(ns_child.text.decode("utf-8"))

            if module:
                if not names:
                    names = [module.split("/")[-1]]  # Side-effect import
                imports.append((module, names, is_relative))

        return imports

    def extract_assignments(self, source: bytes) -> dict[str, str]:
        """Extract assignments: const x = new Foo(), this.x = new Foo()."""
        tree = self._ts_parser.parse(source)
        assignments: dict[str, str] = {}
        self._walk_assignments(tree.root_node, None, assignments)
        return assignments

    def extract_annotations(self, source: bytes) -> dict[str, str]:
        """Extract type annotations from class methods and constructors."""
        tree = self._ts_parser.parse(source)
        annotations: dict[str, str] = {}
        self._walk_annotations(tree.root_node, None, annotations)
        return annotations

    def extract_endpoints(self, source: bytes, file_path: str) -> list[EndpointInfo]:
        """Detect Express router.get/app.post, NestJS decorators, Socket.IO."""
        parser = self._parser_for(file_path)
        tree = parser.parse(source)
        endpoints: list[EndpointInfo] = []
        frameworks = get_endpoint_frameworks("typescript")
        self._walk_ts_endpoints(tree.root_node, file_path, endpoints, frameworks)
        return endpoints

    def extract_data_movements(self, source: bytes, file_path: str) -> list[InteractionInfo]:
        """Detect fetch, axios, Prisma, fs, redis, gRPC calls."""
        parser = self._parser_for(file_path)
        tree = parser.parse(source)
        movements: list[InteractionInfo] = []
        patterns = get_interaction_patterns("typescript")
        self._walk_ts_data_movements(tree.root_node, file_path, movements, patterns)

        # gRPC: if file imports @grpc, match calls on *Client receivers
        imports = self.extract_imports(source)
        has_grpc = any("grpc" in mod for mod, _, _ in imports)
        if has_grpc:
            self._walk_ts_grpc(tree.root_node, file_path, movements)

        return movements

    def _walk_ts_grpc(self, node: Node, file_path: str, movements: list[InteractionInfo]):
        """Detect TypeScript gRPC client calls."""
        if node.type == "call_expression":
            func = node.child_by_field_name("function")
            if func and func.type == "member_expression":
                obj = func.child_by_field_name("object")
                prop = func.child_by_field_name("property")
                if obj and prop:
                    receiver = obj.text.decode("utf-8")
                    method = prop.text.decode("utf-8")
                    if "client" in receiver.lower() or "stub" in receiver.lower():
                        skip = {"close", "getChannel", "waitForReady"}
                        if method not in skip:
                            caller = self._find_enclosing_scope(node)
                            parts = caller.rsplit(".", 1)
                            movements.append(InteractionInfo(
                                source_class=parts[0] if len(parts) > 1 else "",
                                source_method=parts[-1],
                                target=f"{receiver}.{method}",
                                target_type="GRPC_SERVICE",
                                direction="REQUEST_RESPONSE",
                                mechanism="gRPC",
                                file=file_path,
                                line=node.start_point[0] + 1,
                                confidence=0.75,
                            ))
        for child in node.children:
            self._walk_ts_grpc(child, file_path, movements)

    # --- Private: endpoint detection ---

    def _walk_ts_endpoints(self, node: Node, file_path: str,
                           endpoints: list[EndpointInfo], frameworks: dict):
        """Walk for Express-style call patterns: router.get('/path', handler)."""
        if node.type == "call_expression":
            self._check_ts_endpoint_call(node, file_path, endpoints, frameworks)

        for child in node.children:
            self._walk_ts_endpoints(child, file_path, endpoints, frameworks)

    def _check_ts_endpoint_call(self, node: Node, file_path: str,
                                 endpoints: list[EndpointInfo], frameworks: dict):
        """Check if a call matches an endpoint registration pattern."""
        func = node.child_by_field_name("function")
        if not func or func.type != "member_expression":
            return

        obj = func.child_by_field_name("object")
        prop = func.child_by_field_name("property")
        if not obj or not prop:
            return

        receiver = obj.text.decode("utf-8")
        method = prop.text.decode("utf-8")
        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1

        for fw_name, fw_config in frameworks.items():
            for pattern in fw_config.get("call_patterns", []):
                suffix = pattern.get("receiver_suffix", "")
                methods = pattern.get("methods", [])

                if method in methods and (not suffix or receiver.endswith(suffix)):
                    path = self._extract_ts_first_string_arg(node)
                    op = method.upper()
                    if pattern.get("type") == "WEBSOCKET":
                        op = "SUBSCRIBE"
                    endpoints.append(EndpointInfo(
                        type=pattern.get("type", "REST"),
                        path=path,
                        operation=op,
                        handler_class="",
                        handler_method=caller,
                        file=file_path,
                        line=line,
                        direction="INBOUND",
                        protocol=pattern.get("protocol", "HTTP"),
                        framework=fw_name,
                        confidence=0.85,
                    ))
                    return

    def _extract_ts_first_string_arg(self, call_node: Node) -> str:
        """Extract first string argument from a call."""
        args = call_node.child_by_field_name("arguments")
        if args:
            for arg in args.children:
                if arg.type == "string":
                    return self._string_value(arg)
                if arg.type == "template_string":
                    return arg.text.decode("utf-8").strip("`")
        return ""

    # --- Private: data movement detection ---

    def _walk_ts_data_movements(self, node: Node, file_path: str,
                                 movements: list[InteractionInfo], patterns: list[dict]):
        if node.type == "call_expression":
            self._check_ts_data_movement(node, file_path, movements, patterns)

        for child in node.children:
            self._walk_ts_data_movements(child, file_path, movements, patterns)

    def _check_ts_data_movement(self, node: Node, file_path: str,
                                 movements: list[InteractionInfo], patterns: list[dict]):
        func = node.child_by_field_name("function")
        if not func:
            return

        receiver = None
        method = None

        if func.type == "member_expression":
            obj = func.child_by_field_name("object")
            prop = func.child_by_field_name("property")
            if obj and prop:
                receiver = obj.text.decode("utf-8")
                method = prop.text.decode("utf-8")
        elif func.type == "identifier":
            method = func.text.decode("utf-8")

        if not method:
            return

        caller = self._find_enclosing_scope(node)
        caller_parts = caller.rsplit(".", 1)
        source_class = caller_parts[0] if len(caller_parts) > 1 else ""
        source_method = caller_parts[-1]
        line = node.start_point[0] + 1

        for pat in patterns:
            if method not in pat.get("methods", []):
                continue

            pat_receiver = pat.get("receiver")
            pat_suffix = pat.get("receiver_suffix")
            pat_prefix = pat.get("receiver_prefix")

            matched = False
            if pat_receiver is None and receiver is None:
                matched = True
            elif pat_receiver and receiver and pat_receiver in receiver:
                matched = True
            elif pat_suffix and receiver and pat_suffix.lower() in receiver.lower():
                matched = True
            elif pat_prefix and receiver and pat_prefix.lower() in receiver.lower():
                matched = True

            if matched:
                target = self._extract_ts_first_string_arg(node) or f"{receiver or ''}.{method}"
                movements.append(InteractionInfo(
                    source_class=source_class,
                    source_method=source_method,
                    target=target,
                    target_type=pat.get("target_type", "UNKNOWN"),
                    direction=pat.get("direction", "REQUEST_RESPONSE"),
                    mechanism=pat.get("mechanism", ""),
                    file=file_path,
                    line=line,
                    confidence=0.80,
                ))
                break

    # --- Private: call extraction ---

    def _walk_calls(self, node: Node, file_path: str, calls: list[RawCallSite]):
        """Walk AST to find call_expression and new_expression nodes."""
        if node.type == "call_expression":
            call = self._extract_call(node, file_path)
            if call:
                calls.append(call)
        elif node.type == "new_expression":
            call = self._extract_new(node, file_path)
            if call:
                calls.append(call)

        for child in node.children:
            self._walk_calls(child, file_path, calls)

    def _extract_call(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        """Extract from call_expression: foo.bar(), func(), a?.b()."""
        func = node.child_by_field_name("function")
        if not func:
            return None

        caller_name = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1

        if func.type == "member_expression":
            obj = func.child_by_field_name("object")
            prop = func.child_by_field_name("property")
            if obj and prop:
                return RawCallSite(
                    file_path=file_path,
                    caller_name=caller_name,
                    receiver=obj.text.decode("utf-8"),
                    method=prop.text.decode("utf-8"),
                    line=line,
                )

        elif func.type == "identifier":
            name = func.text.decode("utf-8")
            return RawCallSite(
                file_path=file_path,
                caller_name=caller_name,
                receiver=None,
                method=name,
                line=line,
            )

        # Optional chaining: a?.b()
        elif func.type == "optional_chain_expression":
            # Drill into the chain
            return self._extract_optional_chain(func, file_path, caller_name, line)

        return None

    def _extract_new(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        """Extract from new_expression: new Foo()."""
        constructor = node.child_by_field_name("constructor")
        if not constructor:
            return None

        caller_name = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1
        name = constructor.text.decode("utf-8")

        return RawCallSite(
            file_path=file_path,
            caller_name=caller_name,
            receiver=None,
            method=name,
            line=line,
        )

    def _extract_optional_chain(
        self, node: Node, file_path: str, caller_name: str, line: int
    ) -> Optional[RawCallSite]:
        """Extract from optional chain: service?.findById()."""
        # Walk into the chain to find the member access
        for child in node.children:
            if child.type == "member_expression":
                obj = child.child_by_field_name("object")
                prop = child.child_by_field_name("property")
                if obj and prop:
                    return RawCallSite(
                        file_path=file_path,
                        caller_name=caller_name,
                        receiver=obj.text.decode("utf-8"),
                        method=prop.text.decode("utf-8"),
                        line=line,
                    )
        return None

    def _find_enclosing_scope(self, node: Node) -> str:
        """Walk up AST to find enclosing class.method or function name."""
        current = node.parent
        method_name = None
        class_name = None

        while current:
            if current.type == "method_definition" and method_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    method_name = name_node.text.decode("utf-8")

            elif current.type == "function_declaration" and method_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    method_name = name_node.text.decode("utf-8")

            elif current.type == "arrow_function" and method_name is None:
                # Check if assigned to a variable
                parent = current.parent
                if parent and parent.type == "variable_declarator":
                    name_node = parent.child_by_field_name("name")
                    if name_node:
                        method_name = name_node.text.decode("utf-8")

            elif current.type == "class_declaration" and class_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    class_name = name_node.text.decode("utf-8")

            current = current.parent

        if class_name and method_name:
            return f"{class_name}.{method_name}"
        elif method_name:
            return method_name
        return "<module>"

    # --- Private: assignments ---

    def _walk_assignments(self, node: Node, class_name: Optional[str], result: dict):
        """Find this.x = new Foo() and const x = new Foo() patterns."""
        if node.type == "class_declaration":
            name_node = node.child_by_field_name("name")
            cn = name_node.text.decode("utf-8") if name_node else None
            for child in node.children:
                self._walk_assignments(child, cn, result)
            return

        # this.x = new Foo() in constructor/method
        if node.type == "assignment_expression" and class_name:
            left = node.child_by_field_name("left")
            right = node.child_by_field_name("right")
            if left and right and left.type == "member_expression":
                obj = left.child_by_field_name("object")
                prop = left.child_by_field_name("property")
                if obj and prop and obj.text == b"this":
                    attr_name = prop.text.decode("utf-8")
                    resolved = self._resolve_rhs(right)
                    if resolved:
                        result[f"{class_name}.{attr_name}"] = resolved

        # const x = new Foo() / let x = new Foo()
        if node.type == "variable_declarator":
            name_node = node.child_by_field_name("name")
            value_node = node.child_by_field_name("value")
            if name_node and value_node:
                resolved = self._resolve_rhs(value_node)
                if resolved:
                    prefix = f"{class_name}." if class_name else ""
                    result[f"{prefix}{name_node.text.decode('utf-8')}"] = resolved

        for child in node.children:
            self._walk_assignments(child, class_name, result)

    def _resolve_rhs(self, node: Node) -> Optional[str]:
        """If node is new ClassName(), return ClassName."""
        if node.type == "new_expression":
            constructor = node.child_by_field_name("constructor")
            if constructor and constructor.type == "identifier":
                return constructor.text.decode("utf-8")
        return None

    # --- Private: annotations ---

    def _walk_annotations(self, node: Node, class_name: Optional[str], result: dict):
        """Extract type annotations from parameters."""
        if node.type == "class_declaration":
            name_node = node.child_by_field_name("name")
            cn = name_node.text.decode("utf-8") if name_node else None
            for child in node.children:
                self._walk_annotations(child, cn, result)
            return

        if node.type in ("method_definition", "function_declaration") and class_name:
            params = node.child_by_field_name("parameters")
            if params:
                for param in params.named_children:
                    if param.type == "required_parameter":
                        name_node = param.child_by_field_name("pattern")
                        type_node = param.child_by_field_name("type")
                        if name_node and type_node:
                            param_name = name_node.text.decode("utf-8")
                            type_text = type_node.text.decode("utf-8")
                            # Strip leading ': '
                            type_name = type_text.lstrip(": ").split("<")[0].strip()
                            if param_name != "this" and type_name[0:1].isupper():
                                result[f"{class_name}.{param_name}"] = type_name

        for child in node.children:
            self._walk_annotations(child, class_name, result)

    # --- Helpers ---

    @staticmethod
    def _string_value(node: Node) -> str:
        """Extract string content from a string node (strip quotes)."""
        text = node.text.decode("utf-8")
        if (text.startswith("'") and text.endswith("'")) or \
           (text.startswith('"') and text.endswith('"')):
            return text[1:-1]
        return text

"""Go tree-sitter extractor.

Extracts calls, imports, assignments, and type info from Go ASTs.
Handles: call_expression, selector_expression, go_statement, defer_statement,
import_declaration, short_var_declaration, method_declaration with receivers.
"""
from typing import Optional, Any

import tree_sitter_go as ts_go
from tree_sitter import Language, Parser, Node

from src.ast.treesitter_models import RawCallSite
from src.ast.extractors.base import LanguageExtractor
from src.ast.models import EndpointInfo, DataMovementInfo
from src.ast.extractors.endpoint_config import get_endpoint_frameworks, get_data_movement_patterns

GO_LANGUAGE = Language(ts_go.language())


class GoExtractor(LanguageExtractor):
    """Extract call sites, imports, assignments, and type info from Go source."""

    def __init__(self):
        self._parser = Parser(GO_LANGUAGE)

    @property
    def file_extensions(self) -> list[str]:
        return [".go"]

    @property
    def grammar(self) -> Any:
        return GO_LANGUAGE

    def extract_calls(self, source: bytes, file_path: str) -> list[RawCallSite]:
        """Extract all call expressions including goroutines and defers."""
        tree = self._parser.parse(source)
        calls: list[RawCallSite] = []
        self._walk_calls(tree.root_node, file_path, calls)
        return calls

    def extract_imports(self, source: bytes) -> list[tuple[str, list[str], bool]]:
        """Extract import declarations.

        Handles:
        - import "fmt"
        - import ( "fmt" ; "os" )
        - import alias "package/path"
        """
        tree = self._parser.parse(source)
        imports: list[tuple[str, list[str], bool]] = []

        for node in tree.root_node.children:
            if node.type != "import_declaration":
                continue

            for child in node.children:
                if child.type == "import_spec":
                    self._parse_import_spec(child, imports)
                elif child.type == "import_spec_list":
                    for spec in child.children:
                        if spec.type == "import_spec":
                            self._parse_import_spec(spec, imports)

        return imports

    def extract_assignments(self, source: bytes) -> dict[str, str]:
        """Extract variable assignments for type resolution.

        Handles:
        - x := NewFoo()
        - var x Foo = NewFoo()
        - x := &Foo{}
        """
        tree = self._parser.parse(source)
        assignments: dict[str, str] = {}
        self._walk_assignments(tree.root_node, None, assignments)
        return assignments

    def extract_annotations(self, source: bytes) -> dict[str, str]:
        """Extract type info from var declarations.

        Go doesn't have annotations, but typed variable declarations
        serve the same resolution purpose: var db Database.
        """
        tree = self._parser.parse(source)
        annotations: dict[str, str] = {}
        self._walk_type_declarations(tree.root_node, None, annotations)
        return annotations

    def extract_endpoints(self, source: bytes, file_path: str) -> list[EndpointInfo]:
        """Detect http.HandleFunc, mux.Handle, gin.GET/POST etc."""
        tree = self._parser.parse(source)
        endpoints: list[EndpointInfo] = []
        frameworks = get_endpoint_frameworks("go")
        self._walk_go_endpoints(tree.root_node, file_path, endpoints, frameworks)
        return endpoints

    def extract_data_movements(self, source: bytes, file_path: str) -> list[DataMovementInfo]:
        """Detect http.Get, sql.DB queries, redis calls, gRPC stubs."""
        tree = self._parser.parse(source)
        movements: list[DataMovementInfo] = []
        patterns = get_data_movement_patterns("go")
        self._walk_go_data_movements(tree.root_node, file_path, movements, patterns)

        # gRPC detection: if file imports grpc, match calls on pb.* or *Client receivers
        imports = self.extract_imports(source)
        has_grpc = any("grpc" in mod for mod, _, _ in imports)
        if has_grpc:
            self._walk_grpc_calls(tree.root_node, file_path, movements, imports)

        return movements

    def _walk_grpc_calls(self, node: Node, file_path: str,
                         movements: list[DataMovementInfo], imports: list):
        """Detect gRPC stub calls on receivers ending in Client/Stub.

        Only matches receiver.Method() where receiver contains 'client' or 'stub'
        (case-insensitive). Skips infrastructure methods and constructors.
        """
        if node.type == "call_expression":
            func = node.child_by_field_name("function")
            if func and func.type == "selector_expression":
                operand = func.child_by_field_name("operand")
                field_node = func.child_by_field_name("field")
                if operand and field_node:
                    receiver = operand.text.decode("utf-8")
                    method = field_node.text.decode("utf-8")
                    # Only match receivers that look like gRPC clients/stubs
                    recv_lower = receiver.lower()
                    is_grpc_recv = ("client" in recv_lower or "stub" in recv_lower)
                    # Skip infra methods
                    skip = {"Close", "WithDeadlineAfter", "WithCallCredentials",
                            "Dial", "DialContext", "NewServer", "RegisterService",
                            "Serve", "GracefulStop", "Stop", "Wait", "String",
                            "ListenAndServe"}
                    if is_grpc_recv and method not in skip and not method.startswith("New"):
                        caller = self._find_enclosing_scope(node)
                        parts = caller.rsplit(".", 1)
                        movements.append(DataMovementInfo(
                            source_class=parts[0] if len(parts) > 1 else "",
                            source_method=parts[-1],
                            target=f"{receiver}.{method}",
                            target_type="GRPC_SERVICE",
                            direction="REQUEST_RESPONSE",
                            mechanism="gRPC",
                            file=file_path,
                            line=node.start_point[0] + 1,
                            confidence=0.80,
                        ))
        for child in node.children:
            self._walk_grpc_calls(child, file_path, movements, imports)

    # --- Private: endpoint detection ---

    def _walk_go_endpoints(self, node: Node, file_path: str,
                           endpoints: list[EndpointInfo], frameworks: dict):
        if node.type == "call_expression":
            self._check_go_endpoint(node, file_path, endpoints, frameworks)

        for child in node.children:
            self._walk_go_endpoints(child, file_path, endpoints, frameworks)

    def _check_go_endpoint(self, node: Node, file_path: str,
                            endpoints: list[EndpointInfo], frameworks: dict):
        func = node.child_by_field_name("function")
        if not func:
            return

        receiver = None
        method = None

        if func.type == "selector_expression":
            operand = func.child_by_field_name("operand")
            field_node = func.child_by_field_name("field")
            if operand and field_node:
                receiver = operand.text.decode("utf-8")
                method = field_node.text.decode("utf-8")
        elif func.type == "identifier":
            method = func.text.decode("utf-8")

        if not method:
            return

        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1

        for fw_name, fw_config in frameworks.items():
            for pattern in fw_config.get("call_patterns", []):
                suffix = pattern.get("receiver_suffix", "")
                methods = pattern.get("methods", [])

                if method in methods and (not suffix or (receiver and receiver.endswith(suffix))):
                    path = self._extract_go_first_string_arg(node)
                    op = pattern.get("operation", method.upper())
                    if op == "DYNAMIC":
                        op = method.upper()
                    endpoints.append(EndpointInfo(
                        type=pattern.get("type", "REST"),
                        path=path,
                        operation=op,
                        handler_class="",
                        handler_method=caller,
                        file=file_path,
                        line=line,
                        direction="INBOUND",
                        protocol=pattern.get("protocol", "HTTP"),
                        framework=fw_name,
                        confidence=0.85,
                    ))
                    return

    def _extract_go_first_string_arg(self, call_node: Node) -> str:
        args = call_node.child_by_field_name("arguments")
        if args:
            for arg in args.children:
                if arg.type == "interpreted_string_literal":
                    return arg.text.decode("utf-8").strip('"')
                if arg.type == "raw_string_literal":
                    return arg.text.decode("utf-8").strip('`')
        return ""

    # --- Private: data movement detection ---

    def _walk_go_data_movements(self, node: Node, file_path: str,
                                 movements: list[DataMovementInfo], patterns: list[dict]):
        if node.type == "call_expression":
            self._check_go_data_movement(node, file_path, movements, patterns)

        for child in node.children:
            self._walk_go_data_movements(child, file_path, movements, patterns)

    def _check_go_data_movement(self, node: Node, file_path: str,
                                 movements: list[DataMovementInfo], patterns: list[dict]):
        func = node.child_by_field_name("function")
        if not func:
            return

        receiver = None
        method = None

        if func.type == "selector_expression":
            operand = func.child_by_field_name("operand")
            field_node = func.child_by_field_name("field")
            if operand and field_node:
                receiver = operand.text.decode("utf-8")
                method = field_node.text.decode("utf-8")
        elif func.type == "identifier":
            method = func.text.decode("utf-8")

        if not method:
            return

        caller = self._find_enclosing_scope(node)
        caller_parts = caller.rsplit(".", 1)
        source_class = caller_parts[0] if len(caller_parts) > 1 else ""
        source_method = caller_parts[-1]
        line = node.start_point[0] + 1

        for pat in patterns:
            if method not in pat.get("methods", []):
                continue

            pat_receiver = pat.get("receiver")
            matched = False
            if pat_receiver and receiver and pat_receiver in receiver.lower():
                matched = True

            if matched:
                target = self._extract_go_first_string_arg(node) or f"{receiver}.{method}"
                movements.append(DataMovementInfo(
                    source_class=source_class,
                    source_method=source_method,
                    target=target,
                    target_type=pat.get("target_type", "UNKNOWN"),
                    direction=pat.get("direction", "REQUEST_RESPONSE"),
                    mechanism=pat.get("mechanism", ""),
                    file=file_path,
                    line=line,
                    confidence=0.80,
                ))
                break

    # --- Private: call extraction ---

    def _walk_calls(self, node: Node, file_path: str, calls: list[RawCallSite]):
        """Walk AST to find call expressions, go statements, and defer statements."""
        if node.type == "call_expression":
            call = self._extract_call(node, file_path)
            if call:
                calls.append(call)

        elif node.type == "go_statement":
            # go handler() / go func() { ... }()
            for child in node.children:
                if child.type == "call_expression":
                    call = self._extract_call(child, file_path)
                    if call:
                        calls.append(call)

        elif node.type == "defer_statement":
            # defer conn.Close()
            for child in node.children:
                if child.type == "call_expression":
                    call = self._extract_call(child, file_path)
                    if call:
                        calls.append(call)

        for child in node.children:
            self._walk_calls(child, file_path, calls)

    def _extract_call(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        """Extract a call from call_expression."""
        func = node.child_by_field_name("function")
        if not func:
            return None

        caller_name = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1

        if func.type == "selector_expression":
            # pkg.Func() or obj.Method()
            operand = func.child_by_field_name("operand")
            field = func.child_by_field_name("field")
            if operand and field:
                return RawCallSite(
                    file_path=file_path,
                    caller_name=caller_name,
                    receiver=operand.text.decode("utf-8"),
                    method=field.text.decode("utf-8"),
                    line=line,
                )

        elif func.type == "identifier":
            name = func.text.decode("utf-8")
            return RawCallSite(
                file_path=file_path,
                caller_name=caller_name,
                receiver=None,
                method=name,
                line=line,
            )

        return None

    def _find_enclosing_scope(self, node: Node) -> str:
        """Walk up AST to find enclosing function/method."""
        current = node.parent
        func_name = None
        receiver_type = None

        while current:
            if current.type == "function_declaration" and func_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    func_name = name_node.text.decode("utf-8")

            elif current.type == "method_declaration" and func_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    func_name = name_node.text.decode("utf-8")
                # Extract receiver type from the 'receiver' field
                receiver_node = current.child_by_field_name("receiver")
                if receiver_node:
                    receiver_type = self._extract_receiver_type(receiver_node)

            elif current.type == "func_literal" and func_name is None:
                func_name = "<anonymous>"

            current = current.parent

        if receiver_type and func_name:
            return f"{receiver_type}.{func_name}"
        elif func_name:
            return func_name
        return "<module>"

    # --- Private: imports ---

    def _parse_import_spec(self, node: Node, imports: list):
        """Parse a single import_spec node."""
        alias = None
        path = None

        for child in node.children:
            if child.type == "package_identifier":
                alias = child.text.decode("utf-8")
            elif child.type == "interpreted_string_literal":
                path = child.text.decode("utf-8").strip('"')
            elif child.type == "dot":
                alias = "."

        if path:
            # Package name is last component of path
            pkg_name = alias or path.split("/")[-1]
            imports.append((path, [pkg_name], False))

    # --- Private: assignments ---

    def _walk_assignments(self, node: Node, scope: Optional[str], result: dict):
        """Find x := NewFoo() and x := &Foo{} patterns."""
        if node.type == "function_declaration":
            name_node = node.child_by_field_name("name")
            fn = name_node.text.decode("utf-8") if name_node else None
            for child in node.children:
                self._walk_assignments(child, fn, result)
            return

        if node.type == "method_declaration":
            name_node = node.child_by_field_name("name")
            fn = name_node.text.decode("utf-8") if name_node else None
            receiver_node = node.child_by_field_name("receiver")
            recv_type = self._extract_receiver_type(receiver_node)
            scope_name = f"{recv_type}.{fn}" if recv_type and fn else fn
            for child in node.children:
                self._walk_assignments(child, scope_name, result)
            return

        # x := NewFoo() or x := &Foo{}
        if node.type == "short_var_declaration":
            left = node.child_by_field_name("left")
            right = node.child_by_field_name("right")
            if left and right:
                var_names = [c.text.decode("utf-8") for c in left.named_children
                             if c.type == "identifier"]
                resolved = self._resolve_rhs(right)
                if resolved and var_names:
                    prefix = f"{scope}." if scope else ""
                    result[f"{prefix}{var_names[0]}"] = resolved

        for child in node.children:
            self._walk_assignments(child, scope, result)

    def _resolve_rhs(self, node: Node) -> Optional[str]:
        """If node is NewFoo() or &Foo{}, return Foo."""
        # expression_list wraps the RHS
        target = node
        if node.type == "expression_list" and node.named_children:
            target = node.named_children[0]

        # NewFoo() pattern
        if target.type == "call_expression":
            func = target.child_by_field_name("function")
            if func and func.type == "identifier":
                name = func.text.decode("utf-8")
                # Convention: NewFoo -> Foo
                if name.startswith("New") and len(name) > 3:
                    return name[3:]

        # &Foo{} pattern
        if target.type == "unary_expression":
            operand = target.child_by_field_name("operand")
            if operand and operand.type == "composite_literal":
                type_node = operand.child_by_field_name("type")
                if type_node and type_node.type == "type_identifier":
                    return type_node.text.decode("utf-8")

        return None

    # --- Private: type declarations ---

    def _walk_type_declarations(self, node: Node, scope: Optional[str], result: dict):
        """Extract var declarations with explicit types: var db Database."""
        if node.type == "function_declaration":
            name_node = node.child_by_field_name("name")
            fn = name_node.text.decode("utf-8") if name_node else None
            for child in node.children:
                self._walk_type_declarations(child, fn, result)
            return

        if node.type == "method_declaration":
            name_node = node.child_by_field_name("name")
            fn = name_node.text.decode("utf-8") if name_node else None
            receiver_node = node.child_by_field_name("receiver")
            recv_type = self._extract_receiver_type(receiver_node)
            scope_name = f"{recv_type}.{fn}" if recv_type and fn else fn
            for child in node.children:
                self._walk_type_declarations(child, scope_name, result)
            return

        if node.type == "var_declaration":
            for child in node.children:
                if child.type == "var_spec":
                    names = []
                    type_name = None
                    for vc in child.children:
                        if vc.type == "identifier":
                            names.append(vc.text.decode("utf-8"))
                        elif vc.type == "type_identifier":
                            type_name = vc.text.decode("utf-8")
                        elif vc.type == "pointer_type":
                            for pt in vc.children:
                                if pt.type == "type_identifier":
                                    type_name = pt.text.decode("utf-8")
                    if type_name and names:
                        prefix = f"{scope}." if scope else ""
                        for n in names:
                            result[f"{prefix}{n}"] = type_name

        for child in node.children:
            self._walk_type_declarations(child, scope, result)

    def _extract_receiver_type(self, params: Optional[Node]) -> Optional[str]:
        """Extract receiver type from method_declaration parameters."""
        if not params:
            return None
        for param in params.named_children:
            if param.type == "parameter_declaration":
                for pc in param.children:
                    if pc.type == "pointer_type":
                        for pt in pc.children:
                            if pt.type == "type_identifier":
                                return pt.text.decode("utf-8")
                    elif pc.type == "type_identifier":
                        return pc.text.decode("utf-8")
        return None

"""Go tree-sitter extractor.

Extracts calls, imports, assignments, and type info from Go ASTs.
Handles: call_expression, selector_expression, go_statement, defer_statement,
import_declaration, short_var_declaration, method_declaration with receivers.
"""
from typing import Optional, Any

import tree_sitter_go as ts_go
from tree_sitter import Language, Parser, Node

from src.ast.treesitter_models import RawCallSite
from src.ast.extractors.base import LanguageExtractor
from src.ast.models import EndpointInfo, InteractionInfo
from src.ast.extractors.endpoint_config import get_endpoint_frameworks, get_data_movement_patterns

GO_LANGUAGE = Language(ts_go.language())


class GoExtractor(LanguageExtractor):
    """Extract call sites, imports, assignments, and type info from Go source."""

    def __init__(self):
        self._parser = Parser(GO_LANGUAGE)

    @property
    def file_extensions(self) -> list[str]:
        return [".go"]

    @property
    def grammar(self) -> Any:
        return GO_LANGUAGE

    def extract_calls(self, source: bytes, file_path: str) -> list[RawCallSite]:
        """Extract all call expressions including goroutines and defers."""
        tree = self._parser.parse(source)
        calls: list[RawCallSite] = []
        self._walk_calls(tree.root_node, file_path, calls)
        return calls

    def extract_imports(self, source: bytes) -> list[tuple[str, list[str], bool]]:
        """Extract import declarations.

        Handles:
        - import "fmt"
        - import ( "fmt" ; "os" )
        - import alias "package/path"
        """
        tree = self._parser.parse(source)
        imports: list[tuple[str, list[str], bool]] = []

        for node in tree.root_node.children:
            if node.type != "import_declaration":
                continue

            for child in node.children:
                if child.type == "import_spec":
                    self._parse_import_spec(child, imports)
                elif child.type == "import_spec_list":
                    for spec in child.children:
                        if spec.type == "import_spec":
                            self._parse_import_spec(spec, imports)

        return imports

    def extract_assignments(self, source: bytes) -> dict[str, str]:
        """Extract variable assignments for type resolution.

        Handles:
        - x := NewFoo()
        - var x Foo = NewFoo()
        - x := &Foo{}
        """
        tree = self._parser.parse(source)
        assignments: dict[str, str] = {}
        self._walk_assignments(tree.root_node, None, assignments)
        return assignments

    def extract_annotations(self, source: bytes) -> dict[str, str]:
        """Extract type info from var declarations.

        Go doesn't have annotations, but typed variable declarations
        serve the same resolution purpose: var db Database.
        """
        tree = self._parser.parse(source)
        annotations: dict[str, str] = {}
        self._walk_type_declarations(tree.root_node, None, annotations)
        return annotations

    def extract_endpoints(self, source: bytes, file_path: str) -> list[EndpointInfo]:
        """Detect http.HandleFunc, mux.Handle, gin.GET/POST etc."""
        tree = self._parser.parse(source)
        endpoints: list[EndpointInfo] = []
        frameworks = get_endpoint_frameworks("go")
        self._walk_go_endpoints(tree.root_node, file_path, endpoints, frameworks)
        return endpoints

    def extract_data_movements(self, source: bytes, file_path: str) -> list[InteractionInfo]:
        """Detect http.Get, sql.DB queries, redis calls, gRPC stubs."""
        tree = self._parser.parse(source)
        movements: list[InteractionInfo] = []
        patterns = get_data_movement_patterns("go")
        self._walk_go_data_movements(tree.root_node, file_path, movements, patterns)

        # gRPC detection: if file imports grpc, match calls on pb.* or *Client receivers
        imports = self.extract_imports(source)
        has_grpc = any("grpc" in mod for mod, _, _ in imports)
        if has_grpc:
            self._walk_grpc_calls(tree.root_node, file_path, movements, imports)

        return movements

    def _walk_grpc_calls(self, node: Node, file_path: str,
                         movements: list[InteractionInfo], imports: list):
        """Detect gRPC stub calls on receivers ending in Client/Stub.

        Only matches receiver.Method() where receiver contains 'client' or 'stub'
        (case-insensitive). Skips infrastructure methods and constructors.
        """
        if node.type == "call_expression":
            func = node.child_by_field_name("function")
            if func and func.type == "selector_expression":
                operand = func.child_by_field_name("operand")
                field_node = func.child_by_field_name("field")
                if operand and field_node:
                    receiver = operand.text.decode("utf-8")
                    method = field_node.text.decode("utf-8")
                    # Only match receivers that look like gRPC clients/stubs
                    recv_lower = receiver.lower()
                    is_grpc_recv = ("client" in recv_lower or "stub" in recv_lower)
                    # Skip infra methods
                    skip = {"Close", "WithDeadlineAfter", "WithCallCredentials",
                            "Dial", "DialContext", "NewServer", "RegisterService",
                            "Serve", "GracefulStop", "Stop", "Wait", "String",
                            "ListenAndServe"}
                    if is_grpc_recv and method not in skip and not method.startswith("New"):
                        caller = self._find_enclosing_scope(node)
                        parts = caller.rsplit(".", 1)
                        movements.append(InteractionInfo(
                            source_class=parts[0] if len(parts) > 1 else "",
                            source_method=parts[-1],
                            target=f"{receiver}.{method}",
                            target_type="GRPC_SERVICE",
                            direction="REQUEST_RESPONSE",
                            mechanism="gRPC",
                            file=file_path,
                            line=node.start_point[0] + 1,
                            confidence=0.80,
                        ))
        for child in node.children:
            self._walk_grpc_calls(child, file_path, movements, imports)

    # --- Private: endpoint detection ---

    def _walk_go_endpoints(self, node: Node, file_path: str,
                           endpoints: list[EndpointInfo], frameworks: dict):
        if node.type == "call_expression":
            self._check_go_endpoint(node, file_path, endpoints, frameworks)

        for child in node.children:
            self._walk_go_endpoints(child, file_path, endpoints, frameworks)

    def _check_go_endpoint(self, node: Node, file_path: str,
                            endpoints: list[EndpointInfo], frameworks: dict):
        func = node.child_by_field_name("function")
        if not func:
            return

        receiver = None
        method = None

        if func.type == "selector_expression":
            operand = func.child_by_field_name("operand")
            field_node = func.child_by_field_name("field")
            if operand and field_node:
                receiver = operand.text.decode("utf-8")
                method = field_node.text.decode("utf-8")
        elif func.type == "identifier":
            method = func.text.decode("utf-8")

        if not method:
            return

        caller = self._find_enclosing_scope(node)
        line = node.start_point[0] + 1

        for fw_name, fw_config in frameworks.items():
            for pattern in fw_config.get("call_patterns", []):
                suffix = pattern.get("receiver_suffix", "")
                methods = pattern.get("methods", [])

                if method in methods and (not suffix or (receiver and receiver.endswith(suffix))):
                    path = self._extract_go_first_string_arg(node)
                    op = pattern.get("operation", method.upper())
                    if op == "DYNAMIC":
                        op = method.upper()
                    endpoints.append(EndpointInfo(
                        type=pattern.get("type", "REST"),
                        path=path,
                        operation=op,
                        handler_class="",
                        handler_method=caller,
                        file=file_path,
                        line=line,
                        direction="INBOUND",
                        protocol=pattern.get("protocol", "HTTP"),
                        framework=fw_name,
                        confidence=0.85,
                    ))
                    return

    def _extract_go_first_string_arg(self, call_node: Node) -> str:
        args = call_node.child_by_field_name("arguments")
        if args:
            for arg in args.children:
                if arg.type == "interpreted_string_literal":
                    return arg.text.decode("utf-8").strip('"')
                if arg.type == "raw_string_literal":
                    return arg.text.decode("utf-8").strip('`')
        return ""

    # --- Private: data movement detection ---

    def _walk_go_data_movements(self, node: Node, file_path: str,
                                 movements: list[InteractionInfo], patterns: list[dict]):
        if node.type == "call_expression":
            self._check_go_data_movement(node, file_path, movements, patterns)

        for child in node.children:
            self._walk_go_data_movements(child, file_path, movements, patterns)

