"""Integration tests: endpoint & data movement extraction on real open-source repos.

Clones are expected at /tmp/test-repos/<name>. Skip if not present.
Run with: python -m pytest tests/ast/test_real_repos.py -v

Tests validate that our extractors detect known patterns in real codebases:
- nashtech-garage/yas: Java Spring (Kafka, JPA, Redis, WebClient, S3, Elasticsearch)
- dotnet/eShop: C# (MediatR, EF Core, RabbitMQ EventBus, gRPC)
- sqshq/piggymetrics: Java (Feign, Spring Data MongoDB, JavaMail, RabbitMQ)
- AleksK1NG/Go-Kafka-gRPC-MongoDB-microservice: Go (mongo-driver, gRPC, Kafka)
- vendure-ecommerce/vendure: TypeScript (BullMQ, nodemailer, Elasticsearch, EventBus)
- saleor/saleor: Python (Celery, Django ORM, webhooks)
"""
import glob
import pytest
from pathlib import Path

from src.ast.treesitter_provider import TreeSitterProvider
from src.ast.extractors.endpoint_config import reset_caches

REPOS_DIR = Path(r"D:\Work\Gary\test-repos")


def _run_extraction(repo_path: Path, extensions: list[str]):
    """Run tree-sitter extraction on a repo, return merged results."""
    reset_caches()
    files = []
    for ext in extensions:
        files.extend(str(f) for f in repo_path.rglob(f"*{ext}")
                     if ".git" not in str(f) and "node_modules" not in str(f)
                     and "vendor" not in str(f)
                     and not any(p in f.name.lower() for p in ["test", "spec", "mock"]))
    if not files:
        pytest.skip(f"No source files found in {repo_path}")

    provider = TreeSitterProvider()
    results = provider.analyze_batch(files[:800])  # cap at 800 files for speed
    return results, files


def _all_endpoints(results):
    return [ep for a in results.values() for ep in a.endpoints]


def _all_movements(results):
    return [dm for a in results.values() for dm in a.data_movements]


def _movements_by_mechanism(results, mechanism):
    return [dm for dm in _all_movements(results) if dm.mechanism == mechanism]


def _movements_by_type(results, target_type):
    return [dm for dm in _all_movements(results) if dm.target_type == target_type]


def _movements_by_category(results, category_prefix):
    """Match by mechanism prefix or target_type."""
    return [dm for dm in _all_movements(results)
            if category_prefix.lower() in dm.mechanism.lower()
            or category_prefix.lower() in dm.target_type.lower()]


