"""Integration tests: gap-filling repos for untested data movement patterns.

Tests against small focused repos to validate: Redis, RabbitMQ, S3, SignalR,
Mongoose, GORM, SQLAlchemy, gRPC patterns.

Repos expected at D:\\Work\\Gary\\test-repos\\<name>. Skip if not present.
"""
import pytest
from pathlib import Path

from src.ast.treesitter_provider import TreeSitterProvider
from src.ast.extractors.endpoint_config import reset_caches

REPOS_DIR = Path(r"D:\Work\Gary\test-repos")


def _run(repo_name: str, extensions: list[str]):
    reset_caches()
    repo = REPOS_DIR / repo_name
    if not repo.exists():
        pytest.skip(f"{repo_name} not cloned")
    files = []
    for ext in extensions:
        files.extend(str(f) for f in repo.rglob(f"*{ext}")
                     if ".git" not in str(f) and "node_modules" not in str(f)
                     and not any(p in f.name.lower() for p in ["test", "spec", "mock"]))
    if not files:
        pytest.skip(f"No source files in {repo_name}")
    provider = TreeSitterProvider()
    results = provider.analyze_batch(files[:200])
    return results


def _eps(results):
    return [ep for a in results.values() for ep in a.endpoints]


def _dms(results):
    return [dm for a in results.values() for dm in a.data_movements]


def _by_mech(results, mechanism):
    return [dm for dm in _dms(results) if dm.mechanism == mechanism]


