# --- Orchestration ---

def classify(
    self,
    analyses: dict[str, StructuralAnalysis],
    llm_client=None,
    project_root: str = ".",
) -> ClassificationResult:
    """Run full classification: YAML fast path + optional LLM.

    Args:
        analyses: AST extraction results
        llm_client: Optional LLMClient for LLM classification.
                    If None, only YAML fast path runs.
        project_root: Root path for source file reading.

    Returns:
        ClassificationResult with all classified interactions.
    """
    yaml_classified, unclassified = self.detect_unclassified(analyses)
    batches = self.batch_by_framework(unclassified, analyses)

    llm_classified: list[InteractionInfo] = []

    if llm_client and batches:
        from src.ast.interaction_agent import classify_batch

        for batch in batches:
            if batch.framework == "unknown" and not batch.calls:
                continue
            results = classify_batch(batch, llm_client, project_root)
            llm_classified.extend(results)

    total = len(yaml_classified) + len(llm_classified)
    stats = {
        "yaml_classified": len(yaml_classified),
        "llm_classified": len(llm_classified),
        "unclassified_calls": sum(len(b.calls) for b in batches),
        "framework_batches": len(batches),
        "total_interactions": total,
    }

    logger.info(
        f"Classification complete: {stats['yaml_classified']} yaml, "
        f"{stats['llm_classified']} llm, {stats['total_interactions']} total"
    )

    return ClassificationResult(
        yaml_classified=yaml_classified,
        llm_classified=llm_classified,
        unclassified_batches=batches,
        stats=stats,
    )

# --- Output writers ---

@staticmethod
def write_classified_interactions(
    path: Path,
    result: ClassificationResult,
    project_root: str = "",
):
    """Write _interactions.txt with classified_by provenance column."""
    lines = [
        "# type\ttarget\tdirection\tmechanism\tdata_entity\t"
        "source_class\tsource_method\tfile\tline\tconfidence\tclassified_by"
    ]

    def _normalize(file_path: str) -> str:
        if project_root and file_path.startswith(project_root):
            return file_path[len(project_root):].lstrip("/\\")
        return file_path.replace("\\", "/")

    for interaction in result.yaml_classified:
        lines.append(
            f"{interaction.target_type}\t{interaction.target}\t"
            f"{interaction.direction}\t{interaction.mechanism}\t"
            f"{interaction.data_hint}\t{interaction.source_class}\t"
            f"{interaction.source_method}\t{_normalize(interaction.file)}\t"
            f"{interaction.line}\t{interaction.confidence:.2f}\tyaml"
        )

    for interaction in result.llm_classified:
        lines.append(
            f"{interaction.target_type}\t{interaction.target}\t"
            f"{interaction.direction}\t{interaction.mechanism}\t"
            f"{interaction.data_hint}\t{interaction.source_class}\t"
            f"{interaction.source_method}\t{_normalize(interaction.file)}\t"
            f"{interaction.line}\t{interaction.confidence:.2f}\tllm"
        )

    with open(path / "_interactions.txt", "w") as f:
        f.write("\n".join(lines) + "\n")

@staticmethod
def write_auto_discovered_patterns(
    config_path: str,
    new_interactions: list[InteractionInfo],
    repo_name: str = "",
):
    """Append LLM-discovered patterns to auto_discovered_patterns.yaml."""
    if not new_interactions:
        return

    # Load existing
    try:
        with open(config_path) as f:
            existing = yaml.safe_load(f) or {}
    except FileNotFoundError:
        existing = {}

    patterns = existing.get("patterns", [])
    if patterns is None:
        patterns = []

    # Deduplicate by mechanism + method
    existing_keys = {
        (p.get("mechanism", ""), tuple(p.get("methods", [])))
        for p in patterns
    }

    # Group new interactions by mechanism to create patterns
    by_mechanism: dict[str, dict] = {}
    for interaction in new_interactions:
        mech = interaction.mechanism
        if mech not in by_mechanism:
            by_mechanism[mech] = {
                "target_type": interaction.target_type,
                "direction": interaction.direction,
                "mechanism": mech,
                "methods": set(),
                "receivers": set(),
            }
        # Extract method from target (e.g., "kafkaTemplate.send" → "send")
        target = interaction.target
        if "." in target:
            parts = target.rsplit(".", 1)
            by_mechanism[mech]["receivers"].add(parts[0])
            by_mechanism[mech]["methods"].add(parts[1])

    now = datetime.now(timezone.utc).isoformat(timespec="seconds")

    for mech, data in by_mechanism.items():
        methods = sorted(data["methods"])
        key = (mech, tuple(methods))
        if key in existing_keys:
            continue  # Already discovered

        patterns.append({
            "receiver": sorted(data["receivers"])[0] if data["receivers"] else "",
            "methods": methods,
            "target_type": data["target_type"],
            "direction": data["direction"],
            "mechanism": mech,
            "discovered_at": now,
            "source_repo": repo_name,
        })

    existing["patterns"] = patterns

    with open(config_path, "w") as f:
        f.write("# Auto-discovered interaction patterns — generated by LLM classification.\n")
        f.write("# Do not edit manually. Review and promote to interaction_patterns.yaml if correct.\n\n")
        yaml.dump(existing, f, default_flow_style=False, sort_keys=False)

@staticmethod
def write_classification_meta(path: Path, result: ClassificationResult):
    """Write _classification_meta.yaml with stats."""
    meta = {
        "classification": {
            "timestamp": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            "stats": result.stats,
            "framework_batches": [
                {
                    "framework": b.framework,
                    "category": b.category,
                    "language": b.language,
                    "unclassified_calls": len(b.calls),
                }
                for b in result.unclassified_batches
            ],
        }
    }

    with open(path / "_classification_meta.yaml", "w") as f:
        yaml.dump(meta, f, default_flow_style=False, sort_keys=False)

